```ts
// site-log.ts: daily site diary and delay tracking for the project office

export type Weather = "dry" | "rain" | "snow" | "wind";

export interface Entry {
  id: number;
  date: string; // YYYY-MM-DD
  weather: Weather;
  workers: number;
  hoursLost: number;
  notes?: string;
  reportedBy: string;
}

export interface Delay {
  entryId: number;
  cause: "weather" | "supply" | "inspection" | "other";
  hours: number;
}

const entries: Entry[] = [];
const delays: Delay[] = [];
let nextId = 1;

export function addEntry(e: Omit<Entry, "id">): Entry {
  if (e.workers < 0) throw new Error("negative workers");
  const entry = { ...e, id: nextId++ };
  entries.push(entry);
  return entry;
}

export function addDelay(entryId: number, cause: Delay["cause"], hours: number) {
  const entry = entries.find((x) => x.id === entryId);
  if (!entry) throw new Error("no such entry");
  delays.push({ entryId, cause, hours });
  entry.hoursLost = entry.hoursLost + hours;
}

export function entriesBetween(from: string, to: string): Entry[] {
  return entries.filter((e) => e.date >= from && e.date <= to);
}

export function delayHoursByCause(from: string, to: string) {
  const result: Record<string, number> = {};
  const ids = entriesBetween(from, to).map((e) => e.id);
  for (const d of delays) {
    if (ids.includes(d.entryId)) {
      result[d.cause] = (result[d.cause] || 0) + d.hours;
    }
  }
  return result;
}

export function averageCrew(from: string, to: string): number {
  const list = entriesBetween(from, to);
  const total = list.reduce((sum, e) => sum + e.workers, 0);
  return total / list.length;
}

export function weatherDays(from: string, to: string) {
  const counts: any = {};
  entriesBetween(from, to).forEach((e) => {
    counts[e.weather] = (counts[e.weather] || 0) + 1;
  });
  return counts;
}

export function weeklyReport(weekStart: string): string {
  const end = new Date(weekStart);
  end.setDate(end.getDate() + 6);
  const endStr = end.toISOString().slice(0, 10);
  const list = entriesBetween(weekStart, endStr);
  const lost = list.reduce((s, e) => s + e.hoursLost, 0);
  const lines = list.map(
    (e) => `${e.date} ${e.weather} crew=${e.workers} lost=${e.hoursLost}h`
  );
  lines.push(`Total hours lost: ${lost}`);
  lines.push(`Average crew: ${averageCrew(weekStart, endStr).toFixed(1)}`);
  return lines.join("\n");
}
```

This is the booking package from our coworking space system. Can you explain how it works, review it for bugs and design problems, and write table-driven tests for it? Please be specific about edge cases.

```go
package booking

import (
	"errors"
	"sort"
	"sync"
	"time"
)

var (
	ErrOverlap     = errors.New("booking overlaps an existing booking")
	ErrPastTime    = errors.New("booking starts in the past")
	ErrBadDuration = errors.New("booking must last between 30 minutes and 8 hours")
	ErrNoDesk      = errors.New("unknown desk")
)

type Desk struct {
	ID       string
	Capacity int
}

type Booking struct {
	ID     int
	DeskID string
	Member string
	Start  time.Time
	End    time.Time
}

type Calendar struct {
	mu       sync.Mutex
	desks    map[string]Desk
	bookings map[string][]Booking
	nextID   int
	now      func() time.Time
}

func NewCalendar(desks []Desk) *Calendar {
	c := &Calendar{
		desks:    make(map[string]Desk),
		bookings: make(map[string][]Booking),
		now:      time.Now,
	}
	for _, d := range desks {
		c.desks[d.ID] = d
	}
	return c
}

func (c *Calendar) Book(deskID, member string, start, end time.Time) (Booking, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	if _, ok := c.desks[deskID]; !ok {
		return Booking{}, ErrNoDesk
	}
	if start.Before(c.now()) {
		return Booking{}, ErrPastTime
	}
	d := end.Sub(start)
	if d < 30*time.Minute || d > 8*time.Hour {
		return Booking{}, ErrBadDuration
	}
	for _, b := range c.bookings[deskID] {
		if start.Before(b.End) && end.After(b.Start) {
			return Booking{}, ErrOverlap
		}
	}

	c.nextID++
	b := Booking{ID: c.nextID, DeskID: deskID, Member: member, Start: start, End: end}
	c.bookings[deskID] = append(c.bookings[deskID], b)
	return b, nil
}

func (c *Calendar) Cancel(id int) bool {
	c.mu.Lock()
	defer c.mu.Unlock()

	for deskID, list := range c.bookings {
		for i, b := range list {
			if b.ID == id {
				c.bookings[deskID] = append(list[:i], list[i+1:]...)
				return true
			}
		}
	}
	return false
}

func (c *Calendar) ForMember(member string) []Booking {
	c.mu.Lock()
	defer c.mu.Unlock()

	var out []Booking
	for _, list := range c.bookings {
		for _, b := range list {
			if b.Member == member {
				out = append(out, b)
			}
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Start.Before(out[j].Start) })
	return out
}
```

A few things we know. Members book through a web page and also through a door tablet, so several goroutines call Book at once. Members can look up their own bookings from the tablet. We have around forty desks and a few thousand bookings a month, so speed is not the main worry, but correctness is. A member once told us a booking made on the last Sunday of March ended up an hour shorter than they expected, and we never found out why.

This module from our paper mill calculates the cost and expected weight of paper reel orders. Please give it a thorough code review, covering bugs, rounding and numeric problems, structure and naming, and then write a full set of pytest unit tests for it.

```python
import math
from dataclasses import dataclass

# grams per square metre -> price per tonne (euros)
PRICE_PER_TONNE = {
    60: 745.0,
    80: 790.0,
    100: 815.0,
    120: 860.0,
}

CORE_WEIGHT_KG = 12.5
MAX_REEL_DIAMETER_M = 1.25
CORE_DIAMETER_M = 0.15


@dataclass
class Order:
    customer: str
    gsm: int
    width_m: float
    length_m: float
    quantity: int
    rush: bool = False


def sheet_weight_kg(gsm, width_m, length_m):
    area = width_m * length_m
    return area * gsm / 1000


def reel_weight_kg(order):
    paper = sheet_weight_kg(order.gsm, order.width_m, order.length_m)
    return paper + CORE_WEIGHT_KG


def reel_diameter_m(order):
    # thickness in mm is roughly gsm / 1000 * 1.2
    thickness_m = order.gsm / 1000 * 1.2 / 1000
    r_core = CORE_DIAMETER_M / 2
    r_out = math.sqrt(r_core ** 2 + order.length_m * thickness_m / math.pi)
    return r_out * 2


def price_per_tonne(gsm):
    if gsm in PRICE_PER_TONNE:
        return PRICE_PER_TONNE[gsm]
    keys = sorted(PRICE_PER_TONNE)
    for lo, hi in zip(keys, keys[1:]):
        if lo < gsm < hi:
            share = (gsm - lo) / (hi - lo)
            return PRICE_PER_TONNE[lo] + share * (PRICE_PER_TONNE[hi] - PRICE_PER_TONNE[lo])
    raise ValueError("unsupported gsm")


def order_cost(order):
    if order.quantity <= 0:
        raise ValueError("quantity must be positive")
    if reel_diameter_m(order) > MAX_REEL_DIAMETER_M:
        raise ValueError("reel too large")
    paper_tonnes = sheet_weight_kg(order.gsm, order.width_m, order.length_m) * order.quantity / 1000
    cost = paper_tonnes * price_per_tonne(order.gsm)
    if order.quantity >= 20:
        cost = cost * 0.95
    elif order.quantity >= 10:
        cost = cost * 0.97
    if order.rush:
        cost += cost * 0.15
    return round(cost, 2)
```

Some notes on how it is used. The sales office types orders into a small web form, which builds an Order and shows the cost to the customer before they confirm. Widths are usually between 0.5 and 1.6 metres and lengths between 500 and 6,000 metres. Last month a customer was quoted a price a few euros lower than the invoice, and we also had one reel that came off the machine heavier than the paperwork said. The sales office would like to know whether those two incidents could come from this code.

