```typescript
export type Material = "pottery" | "bone" | "metal" | "stone" | "glass";

export interface Find {
  id: string;
  trench: string;
  layer: number;
  material: Material;
  weightG: number;
  depthCm: number;
  foundAt: Date;
  notes?: string;
}

const REQUIRED_PREFIX: Record<Material, string> = {
  pottery: "PT",
  bone: "BN",
  metal: "MT",
  stone: "ST",
  glass: "GL",
};

let counter = 0;

export function makeId(trench: string, material: Material): string {
  counter++;
  return `${trench.toUpperCase()}-${REQUIRED_PREFIX[material]}-${counter.toString().padStart(4, "0")}`;
}

export function logFind(
  list: Find[],
  trench: string,
  layer: number,
  material: Material,
  weightG: number,
  depthCm: number,
  notes?: string
): Find {
  if (weightG < 0) throw new Error("negative weight");
  if (depthCm < 0 || depthCm > 400) throw new Error("depth out of range");
  const find: Find = {
    id: makeId(trench, material),
    trench,
    layer,
    material,
    weightG,
    depthCm,
    foundAt: new Date(),
    notes,
  };
  list.push(find);
  return find;
}

export function totalsByMaterial(list: Find[]): Record<string, number> {
  const out: Record<string, number> = {};
  for (const f of list) {
    out[f.material] = (out[f.material] || 0) + f.weightG;
  }
  return out;
}

export function findsInLayer(list: Find[], trench: string, layer: number): Find[] {
  return list.filter((f) => f.trench == trench && f.layer == layer);
}

export function deepest(list: Find[]): Find | undefined {
  let best: Find | undefined;
  for (const f of list) {
    if (!best || f.depthCm > best.depthCm) best = f;
  }
  return best;
}

export function toCsv(list: Find[]): string {
  const header = "id,trench,layer,material,weightG,depthCm,foundAt,notes";
  const rows = list.map(
    (f) =>
      [f.id, f.trench, f.layer, f.material, f.weightG, f.depthCm, f.foundAt.toISOString(), f.notes ?? ""].join(",")
  );
  return [header, ...rows].join("\n");
}

export function dailySummary(list: Find[], day: Date): string {
  const same = list.filter((f) => f.foundAt.getDate() === day.getDate());
  const totals = totalsByMaterial(same);
  const lines = Object.keys(totals).map((m) => `${m}: ${totals[m]} g`);
  return `${same.length} finds on ${day.toDateString()}\n${lines.join("\n")}`;
}
```

Some background: students work in teams of four per trench, and each team has a tablet that runs this code in a browser page. The students type notes freely, and last season some notes contained commas and quotation marks, which broke the CSV import into the university database. We also had two teams who both recorded finds called "A1-PT-0007", and the field school runs for six weeks, from June into July. At the end of each day the supervisor prints the daily summary for every trench.

Here is a Go package from our tea importing business that works out the blend recipes for our packaged teas. Please explain what each function does, review it for bugs and design issues, and write table-driven tests. I'm especially worried about the rounding and about the ordering of results.

```go
package blend

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

type Lot struct {
	Name        string
	Origin      string
	GramsInHand float64
	CostPerKg   float64
}

type Part struct {
	LotName string
	Percent float64
}

type Recipe struct {
	Name  string
	Parts []Part
}

var ErrShortStock = errors.New("not enough stock for batch")

func Validate(r Recipe) error {
	total := 0.0
	for _, p := range r.Parts {
		if p.Percent <= 0 {
			return fmt.Errorf("recipe %s: non-positive share for %s", r.Name, p.LotName)
		}
		total += p.Percent
	}
	if total != 100 {
		return fmt.Errorf("recipe %s: shares add up to %v, want 100", r.Name, total)
	}
	return nil
}

func CostPerKg(r Recipe, stock map[string]*Lot) (float64, error) {
	cost := 0.0
	for _, p := range r.Parts {
		lot, ok := stock[p.LotName]
		if !ok {
			return 0, fmt.Errorf("unknown lot %q", p.LotName)
		}
		cost += lot.CostPerKg * p.Percent / 100
	}
	return cost, nil
}

func Needs(r Recipe, batchKg float64) map[string]float64 {
	out := make(map[string]float64)
	for _, p := range r.Parts {
		out[p.LotName] += batchKg * 1000 * p.Percent / 100
	}
	return out
}

func Produce(r Recipe, batchKg float64, stock map[string]*Lot) error {
	if err := Validate(r); err != nil {
		return err
	}
	needs := Needs(r, batchKg)
	for name, grams := range needs {
		lot, ok := stock[name]
		if !ok {
			return fmt.Errorf("unknown lot %q", name)
		}
		if lot.GramsInHand < grams {
			return ErrShortStock
		}
		lot.GramsInHand -= grams
	}
	return nil
}

func Label(r Recipe) string {
	var names []string
	for _, p := range r.Parts {
		names = append(names, p.LotName)
	}
	sort.Strings(names)
	return r.Name + ": " + strings.Join(names, ", ")
}
```

Some context. Recipes are loaded from a spreadsheet, so percentages like 33.3, 33.3 and 33.4 do appear, as do thirds that someone typed as 33.333. A batch is usually 5 to 40 kg. We have about 60 lots in stock and 25 recipes. The warehouse team once reported that a failed batch had still used up part of the stock of one lot, even though the system said the batch was refused. The label is printed on the box and is read by customers, so the order in which the ingredients appear matters to us for legal reasons: they have to be listed from the largest share to the smallest.

This package decides whether a customer in our mobile banking app may send a transfer, based on daily limits and a velocity check. Please explain how it works, review it for bugs and design problems (I suspect there are a few around concurrency and money handling), and write table-driven tests that cover the important behaviour.

```go
// Package limits decides whether a transfer may proceed, based on
// per-customer daily limits and a short-term velocity check.
package limits

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Amount is a value in minor currency units (cents).
type Amount int64

// Tier controls the daily limit a customer gets.
type Tier int

const (
	TierBasic Tier = iota
	TierStandard
	TierPremium
)

var dailyLimit = map[Tier]Amount{
	TierBasic:    50000,
	TierStandard: 250000,
	TierPremium:  1000000,
}

var (
	ErrDailyLimit   = errors.New("daily limit exceeded")
	ErrVelocity     = errors.New("too many transfers in a short time")
	ErrInvalidSum   = errors.New("amount must be positive")
	ErrUnknownTier  = errors.New("unknown customer tier")
	ErrNewPayeeCap  = errors.New("amount too high for a new payee")
)

// Transfer is a request to move money to a payee.
type Transfer struct {
	CustomerID string
	PayeeID    string
	Amount     Amount
	At         time.Time
}

type record struct {
	amount Amount
	at     time.Time
}

// Checker keeps recent transfers in memory.
type Checker struct {
	mu          sync.Mutex
	history     map[string][]record
	knownPayees map[string]map[string]bool
	tiers       map[string]Tier
	window      time.Duration
	maxInWindow int
	newPayeeCap Amount
}

// NewChecker builds a checker. A window of zero disables the velocity check.
func NewChecker(window time.Duration, maxInWindow int, newPayeeCap Amount) *Checker {
	return &Checker{
		history:     make(map[string][]record),
		knownPayees: make(map[string]map[string]bool),
		tiers:       make(map[string]Tier),
		window:      window,
		maxInWindow: maxInWindow,
		newPayeeCap: newPayeeCap,
	}
}

// SetTier assigns a tier to a customer.
func (c *Checker) SetTier(customerID string, t Tier) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.tiers[customerID] = t
}

// AddPayee marks a payee as known for a customer.
func (c *Checker) AddPayee(customerID, payeeID string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.knownPayees[customerID] == nil {
		c.knownPayees[customerID] = make(map[string]bool)
	}
	c.knownPayees[customerID][payeeID] = true
}

// Allow checks a transfer and, if it is allowed, records it.
func (c *Checker) Allow(t Transfer) error {
	if t.Amount <= 0 {
		return ErrInvalidSum
	}

	c.mu.Lock()
	defer c.mu.Unlock()

	tier, ok := c.tiers[t.CustomerID]
	if !ok {
		tier = TierBasic
	}
	limit, ok := dailyLimit[tier]
	if !ok {
		return ErrUnknownTier
	}

	if !c.knownPayees[t.CustomerID][t.PayeeID] && t.Amount > c.newPayeeCap {
		return fmt.Errorf("%w: %d > %d", ErrNewPayeeCap, t.Amount, c.newPayeeCap)
	}

	var spentToday Amount
	var recent int
	for _, r := range c.history[t.CustomerID] {
		if sameDay(r.at, t.At) {
			spentToday += r.amount
		}
		if c.window > 0 && t.At.Sub(r.at) < c.window {
			recent++
		}
	}

	if spentToday+t.Amount > limit {
		return fmt.Errorf("%w: %d of %d already used", ErrDailyLimit, spentToday, limit)
	}
	if c.window > 0 && recent >= c.maxInWindow {
		return ErrVelocity
	}

	c.history[t.CustomerID] = append(c.history[t.CustomerID], record{t.Amount, t.At})
	return nil
}

// Remaining returns how much a customer may still send today.
func (c *Checker) Remaining(customerID string, now time.Time) Amount {
	c.mu.Lock()
	defer c.mu.Unlock()

	tier := c.tiers[customerID]
	var spent Amount
	for _, r := range c.history[customerID] {
		if sameDay(r.at, now) {
			spent += r.amount
		}
	}
	return dailyLimit[tier] - spent
}

// Prune drops history older than two days to keep memory bounded.
func (c *Checker) Prune(now time.Time) {
	cutoff := now.Add(-48 * time.Hour)
	for id, recs := range c.history {
		kept := recs[:0]
		for _, r := range recs {
			if r.at.After(cutoff) {
				kept = append(kept, r)
			}
		}
		if len(kept) == 0 {
			delete(c.history, id)
		} else {
			c.history[id] = kept
		}
	}
}

func sameDay(a, b time.Time) bool {
	ay, am, ad := a.Date()
	by, bm, bd := b.Date()
	return ay == by && am == bm && ad == bd
}
```

Some background from the team: customers are across three time zones, the app server runs in UTC, and transfers are submitted by up to a few hundred goroutines at once. A cancelled transfer is never un-recorded at the moment, and we plan to move the history into a database next quarter, so I would like the review to say what the interface should look like to make that easy.

This module handles hold requests and loan renewals for our university library's catalogue service. Please explain what each part does, propose a refactoring that would make it easier to maintain, and write tests for the refactored version (Vitest is fine). If you see bugs in the current version, point them out as you go.

```ts
import { randomUUID } from "node:crypto";

export type Role = "undergraduate" | "postgraduate" | "staff" | "visitor";

export interface Patron {
  id: string;
  name: string;
  role: Role;
  finesPence: number;
  suspended: boolean;
}

export interface Item {
  id: string;
  title: string;
  isbn?: string;
  loanType: "standard" | "short" | "reference";
  copies: number;
  availableCopies: number;
}

export interface Loan {
  id: string;
  patronId: string;
  itemId: string;
  borrowedOn: Date;
  dueOn: Date;
  renewals: number;
  returnedOn?: Date;
}

export interface Hold {
  id: string;
  patronId: string;
  itemId: string;
  placedOn: Date;
  status: "waiting" | "ready" | "cancelled" | "fulfilled";
}

const LOAN_DAYS: Record<Role, number> = {
  undergraduate: 21,
  postgraduate: 42,
  staff: 60,
  visitor: 7,
};

const MAX_RENEWALS: Record<Role, number> = {
  undergraduate: 2,
  postgraduate: 4,
  staff: 6,
  visitor: 0,
};

const FINE_BLOCK_PENCE = 1000;
const MAX_ACTIVE_HOLDS = 5;

export class LibraryService {
  private loans: Loan[] = [];
  private holds: Hold[] = [];

  constructor(
    private patrons: Map<string, Patron>,
    private items: Map<string, Item>,
  ) {}

  placeHold(patronId: string, itemId: string): Hold {
    const patron = this.patrons.get(patronId);
    const item = this.items.get(itemId);
    if (!patron || !item) throw new Error("Unknown patron or item");
    if (patron.suspended) throw new Error("Account suspended");
    if (patron.finesPence >= FINE_BLOCK_PENCE) throw new Error("Fines too high");
    if (item.loanType === "reference") throw new Error("Reference items cannot be held");

    const active = this.holds.filter(
      (h) => h.patronId === patronId && (h.status === "waiting" || h.status === "ready"),
    );
    if (active.length > MAX_ACTIVE_HOLDS) throw new Error("Too many holds");
    if (active.some((h) => h.itemId === itemId)) throw new Error("Already on hold");

    const hold: Hold = {
      id: randomUUID(),
      patronId,
      itemId,
      placedOn: new Date(),
      status: item.availableCopies > 0 ? "ready" : "waiting",
    };
    if (hold.status === "ready") item.availableCopies--;
    this.holds.push(hold);
    return hold;
  }

  borrow(patronId: string, itemId: string, today = new Date()): Loan {
    const patron = this.patrons.get(patronId);
    const item = this.items.get(itemId);
    if (!patron || !item) throw new Error("Unknown patron or item");
    if (patron.suspended) throw new Error("Account suspended");
    if (item.loanType === "reference") throw new Error("Reference items cannot be borrowed");

    const ready = this.holds.find(
      (h) => h.patronId === patronId && h.itemId === itemId && h.status === "ready",
    );
    if (ready) {
      ready.status = "fulfilled";
    } else {
      if (item.availableCopies <= 0) throw new Error("No copies available");
      item.availableCopies--;
    }

    const days = item.loanType === "short" ? 3 : LOAN_DAYS[patron.role];
    const due = new Date(today);
    due.setDate(due.getDate() + days);
    const loan: Loan = {
      id: randomUUID(),
      patronId,
      itemId,
      borrowedOn: today,
      dueOn: due,
      renewals: 0,
    };
    this.loans.push(loan);
    return loan;
  }

  renew(loanId: string, today = new Date()): Loan {
    const loan = this.loans.find((l) => l.id === loanId);
    if (!loan || loan.returnedOn) throw new Error("No such active loan");
    const patron = this.patrons.get(loan.patronId)!;
    const item = this.items.get(loan.itemId)!;

    if (patron.suspended) throw new Error("Account suspended");
    if (loan.renewals >= MAX_RENEWALS[patron.role]) throw new Error("Renewal limit reached");
    if (loan.dueOn < today) throw new Error("Loan is overdue");

    const waiting = this.holds.some((h) => h.itemId === item.id && h.status === "waiting");
    if (waiting) throw new Error("Item requested by another patron");

    const days = item.loanType === "short" ? 3 : LOAN_DAYS[patron.role];
    loan.dueOn.setDate(loan.dueOn.getDate() + days);
    loan.renewals += 1;
    return loan;
  }

  giveBack(loanId: string, today = new Date()): number {
    const loan = this.loans.find((l) => l.id === loanId);
    if (!loan || loan.returnedOn) throw new Error("No such active loan");
    loan.returnedOn = today;

    const item = this.items.get(loan.itemId)!;
    const next = this.holds
      .filter((h) => h.itemId === item.id && h.status === "waiting")
      .sort((a, b) => a.placedOn.getTime() - b.placedOn.getTime())[0];
    if (next) {
      next.status = "ready";
    } else {
      item.availableCopies++;
    }

    const lateDays = Math.max(
      0,
      Math.floor((today.getTime() - loan.dueOn.getTime()) / 86_400_000),
    );
    const fine = lateDays * 25;
    this.patrons.get(loan.patronId)!.finesPence += fine;
    return fine;
  }
}
```

Context: this class lives in memory today and is rebuilt from the database on every deployment. We plan to back it with a real store, and the front desk staff have complained that reference items sometimes show as available to hold. The loan period for staff was changed from 42 to 60 days in September.

Please explain what each part of this TypeScript module does, propose a refactoring that would make it easier to maintain, and write tests for the refactored version. It's the eligibility and appointment logic for the Riverbend Blood Service booking site, and it has grown messy over the last year. I'd like to know where the hidden bugs are before we add platelet donations.

```typescript
export type DonationType = "whole" | "plasma" | "platelets";

export interface Donor {
  id: string;
  birthDate: string; // ISO date
  weightKg: number;
  lastDonation?: { date: string; type: DonationType };
  deferredUntil?: string; // ISO date
  haemoglobin?: number; // g/L, from the last screening
  sex: "f" | "m";
}

export interface Slot {
  id: string;
  centre: string;
  start: string; // ISO datetime
  capacity: number;
  booked: number;
  types: DonationType[];
}

export interface Booking {
  slotId: string;
  donorId: string;
  type: DonationType;
  createdAt: string;
}

const DAY = 24 * 60 * 60 * 1000;

const WAIT_DAYS: Record<DonationType, number> = {
  whole: 84,
  plasma: 14,
  platelets: 7,
};

export function ageOn(birthDate: string, on: Date): number {
  const b = new Date(birthDate);
  let age = on.getFullYear() - b.getFullYear();
  if (
    on.getMonth() < b.getMonth() ||
    (on.getMonth() === b.getMonth() && on.getDate() < b.getDate())
  ) {
    age--;
  }
  return age;
}

export function eligibility(
  donor: Donor,
  type: DonationType,
  on: Date
): { ok: boolean; reason?: string } {
  const age = ageOn(donor.birthDate, on);
  if (age < 18) return { ok: false, reason: "under 18" };
  if (age > 70) return { ok: false, reason: "over 70" };
  if (donor.weightKg < 50) return { ok: false, reason: "under 50 kg" };

  if (donor.deferredUntil && new Date(donor.deferredUntil) > on) {
    return { ok: false, reason: "deferred until " + donor.deferredUntil };
  }

  if (type === "whole" || type === "platelets") {
    const min = donor.sex === "f" ? 125 : 135;
    if (donor.haemoglobin !== undefined && donor.haemoglobin < min) {
      return { ok: false, reason: "haemoglobin too low" };
    }
  }

  if (donor.lastDonation) {
    const last = new Date(donor.lastDonation.date);
    const days = Math.floor((on.getTime() - last.getTime()) / DAY);
    const wait = WAIT_DAYS[donor.lastDonation.type];
    if (days < wait) {
      return { ok: false, reason: `wait ${wait - days} more days` };
    }
  }

  return { ok: true };
}

export function openSlots(
  slots: Slot[],
  type: DonationType,
  centre?: string
): Slot[] {
  return slots
    .filter((s) => s.types.includes(type))
    .filter((s) => !centre || s.centre === centre)
    .filter((s) => s.booked < s.capacity)
    .sort((a, b) => a.start.localeCompare(b.start));
}

export function nextEligibleDate(donor: Donor, type: DonationType): Date {
  let date = new Date();
  if (donor.lastDonation) {
    const last = new Date(donor.lastDonation.date);
    const wait = WAIT_DAYS[donor.lastDonation.type];
    const earliest = new Date(last.getTime() + wait * DAY);
    if (earliest > date) date = earliest;
  }
  if (donor.deferredUntil) {
    const deferred = new Date(donor.deferredUntil);
    if (deferred > date) date = deferred;
  }
  if (type === "platelets" && donor.lastDonation?.type === "whole") {
    // platelets need a longer gap after a whole blood donation
    const extra = new Date(
      new Date(donor.lastDonation.date).getTime() + 28 * DAY
    );
    if (extra > date) date = extra;
  }
  return date;
}

export class BookingService {
  private bookings: Booking[] = [];

  constructor(
    private slots: Slot[],
    private donors: Map<string, Donor>,
    private now: () => Date = () => new Date()
  ) {}

  book(donorId: string, slotId: string, type: DonationType): Booking {
    const donor = this.donors.get(donorId);
    if (!donor) throw new Error("unknown donor");
    const slot = this.slots.find((s) => s.id === slotId);
    if (!slot) throw new Error("unknown slot");

    if (!slot.types.includes(type)) {
      throw new Error("slot does not offer " + type);
    }
    if (slot.booked >= slot.capacity) {
      throw new Error("slot is full");
    }

    const result = eligibility(donor, type, new Date(slot.start));
    if (!result.ok) {
      throw new Error("not eligible: " + result.reason);
    }

    const existing = this.bookings.find(
      (b) => b.donorId === donorId && b.slotId === slotId
    );
    if (existing) return existing;

    const booking: Booking = {
      slotId,
      donorId,
      type,
      createdAt: this.now().toISOString(),
    };
    this.bookings.push(booking);
    slot.booked += 1;
    return booking;
  }

  cancel(donorId: string, slotId: string): boolean {
    const index = this.bookings.findIndex(
      (b) => b.donorId === donorId && b.slotId === slotId
    );
    if (index < 0) return false;
    this.bookings.splice(index, 1);
    const slot = this.slots.find((s) => s.id === slotId);
    if (slot) slot.booked -= 1;
    return true;
  }

  upcoming(donorId: string): Booking[] {
    const now = this.now().getTime();
    return this.bookings
      .filter((b) => b.donorId === donorId)
      .filter((b) => {
        const slot = this.slots.find((s) => s.id === b.slotId);
        return slot ? new Date(slot.start).getTime() > now : false;
      });
  }

  reminderList(hoursAhead: number): { donorId: string; start: string }[] {
    const now = this.now().getTime();
    const limit = now + hoursAhead * 60 * 60 * 1000;
    const out: { donorId: string; start: string }[] = [];
    for (const b of this.bookings) {
      const slot = this.slots.find((s) => s.id === b.slotId);
      if (!slot) continue;
      const t = new Date(slot.start).getTime();
      if (t > now && t <= limit) {
        out.push({ donorId: b.donorId, start: slot.start });
      }
    }
    return out;
  }
}
```

I'm new to Go and inherited this package from a colleague who left our courier startup. Could you explain what it does piece by piece, review it for bugs and bad style, and write table-driven tests for the important functions? Please tell me which bugs would hurt customers first.

```go
// Package dispatch assigns parcels to couriers for Quickfoot Couriers and
// estimates delivery prices and times.
package dispatch

import (
	"errors"
	"math"
	"sort"
	"sync"
	"time"
)

type Point struct {
	Lat, Lon float64
}

type Parcel struct {
	ID       string
	Weight   float64 // kilograms
	Pickup   Point
	Dropoff  Point
	Deadline time.Time
	Fragile  bool
}

type Courier struct {
	ID       string
	Location Point
	Vehicle  string // "bike", "van"
	Load     float64
	MaxLoad  float64
	OnShift  bool
}

var ErrNoCourier = errors.New("no courier available")

// distanceKm returns the straight-line distance in kilometres using the
// haversine formula.
func distanceKm(a, b Point) float64 {
	const earthRadius = 6371.0
	dLat := (b.Lat - a.Lat) * math.Pi / 180
	dLon := (b.Lon - a.Lon) * math.Pi / 180
	la := a.Lat * math.Pi / 180
	lb := b.Lat * math.Pi / 180
	h := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(la)*math.Cos(lb)*math.Sin(dLon/2)*math.Sin(dLon/2)
	return 2 * earthRadius * math.Asin(math.Sqrt(h))
}

// Price returns the delivery price in euro cents.
func Price(p Parcel) int {
	km := distanceKm(p.Pickup, p.Dropoff)
	price := 350 + int(km*90)
	if p.Weight > 5 {
		price += int((p.Weight - 5) * 40)
	}
	if p.Fragile {
		price += 200
	}
	if price > 4000 {
		price = 4000
	}
	return price
}

// ETA estimates how long a courier needs to collect and deliver a parcel.
func ETA(c Courier, p Parcel) time.Duration {
	speed := 15.0 // km/h for bikes
	if c.Vehicle == "van" {
		speed = 25.0
	}
	km := distanceKm(c.Location, p.Pickup) + distanceKm(p.Pickup, p.Dropoff)
	hours := km / speed
	return time.Duration(hours*float64(time.Hour)) + 5*time.Minute
}

// Pool holds the couriers that are currently known to the dispatcher.
type Pool struct {
	mu       sync.Mutex
	couriers map[string]*Courier
}

func NewPool() *Pool {
	return &Pool{couriers: make(map[string]*Courier)}
}

func (p *Pool) Add(c Courier) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.couriers[c.ID] = &c
}

func (p *Pool) UpdateLocation(id string, loc Point) bool {
	c, ok := p.couriers[id]
	if !ok {
		return false
	}
	c.Location = loc
	return true
}

func (p *Pool) SetShift(id string, on bool) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if c, ok := p.couriers[id]; ok {
		c.OnShift = on
	}
}

// Candidates returns couriers that could carry the parcel, nearest first.
func (p *Pool) Candidates(parcel Parcel) []*Courier {
	p.mu.Lock()
	defer p.mu.Unlock()

	var out []*Courier
	for _, c := range p.couriers {
		if !c.OnShift {
			continue
		}
		if c.Load+parcel.Weight > c.MaxLoad {
			continue
		}
		if parcel.Weight > 20 && c.Vehicle == "bike" {
			continue
		}
		out = append(out, c)
	}

	sort.Slice(out, func(i, j int) bool {
		return distanceKm(out[i].Location, parcel.Pickup) <
			distanceKm(out[j].Location, parcel.Pickup)
	})
	return out
}

// Assign picks the nearest suitable courier whose ETA meets the deadline and
// adds the parcel weight to their load.
func (p *Pool) Assign(parcel Parcel, now time.Time) (*Courier, error) {
	cands := p.Candidates(parcel)
	for _, c := range cands {
		if now.Add(ETA(*c, parcel)).Before(parcel.Deadline) {
			c.Load += parcel.Weight
			return c, nil
		}
	}
	return nil, ErrNoCourier
}

// Release removes the weight of a delivered parcel from a courier's load.
func (p *Pool) Release(id string, weight float64) {
	c := p.couriers[id]
	c.Load -= weight
	if c.Load < 0 {
		c.Load = 0
	}
}

// Batch groups parcels with the same pickup point so one courier can collect
// them together. Parcels are grouped when their pickups are within 150 metres.
func Batch(parcels []Parcel) [][]Parcel {
	var groups [][]Parcel
	used := make([]bool, len(parcels))
	for i := range parcels {
		if used[i] {
			continue
		}
		group := []Parcel{parcels[i]}
		used[i] = true
		for j := i + 1; j < len(parcels); j++ {
			if used[j] {
				continue
			}
			if distanceKm(parcels[i].Pickup, parcels[j].Pickup) < 0.15 {
				group = append(group, parcels[j])
				used[j] = true
			}
		}
		groups = append(groups, group)
	}
	return groups
}

// Summary describes the state of the pool for the operations dashboard.
type Summary struct {
	OnShift   int
	Idle      int
	TotalLoad float64
	Capacity  float64
}

// Summarise counts couriers on shift and how much of their capacity is used.
func (p *Pool) Summarise() Summary {
	var s Summary
	for _, c := range p.couriers {
		if !c.OnShift {
			continue
		}
		s.OnShift++
		if c.Load == 0 {
			s.Idle++
		}
		s.TotalLoad += c.Load
		s.Capacity += c.MaxLoad
	}
	return s
}
```

Could you do a careful code review of this Python module and then write a complete pytest suite for it? It plans the order in which hull blocks are lifted into the dock at our shipyard, and it also checks crane limits. I suspect there are bugs in the dependency handling and in the crane check, and I'd like you to say which problems are serious and which are only style.

```python
"""block_plan.py - hull block erection planning for Dunmore Slipway.

A hull is built from blocks. A block can only be lifted into the dock when all
blocks it rests on are already in place. Each lift needs a crane that can
carry the block's weight at the required radius.
"""

import heapq
from collections import defaultdict, deque


class PlanError(Exception):
    pass


class Block:
    def __init__(self, name, weight_t, radius_m, hours, rests_on=None):
        self.name = name
        self.weight_t = weight_t
        self.radius_m = radius_m
        self.hours = hours
        self.rests_on = rests_on or []

    def __repr__(self):
        return "Block(%s)" % self.name


class Crane:
    def __init__(self, name, curve):
        # curve: list of (radius_m, max_weight_t), sorted by radius
        self.name = name
        self.curve = curve
        self.free_at = 0

    def capacity_at(self, radius):
        last = None
        for r, w in self.curve:
            if radius <= r:
                if last is None:
                    return w
                lr, lw = last
                return lw + (w - lw) * (radius - lr) / (r - lr)
            last = (r, w)
        return 0

    def can_lift(self, block):
        return block.weight_t <= self.capacity_at(block.radius_m)


def build_graph(blocks):
    by_name = {}
    for b in blocks:
        by_name[b.name] = b
    children = defaultdict(list)
    indegree = {}
    for b in blocks:
        indegree[b.name] = len(b.rests_on)
        for dep in b.rests_on:
            if dep not in by_name:
                raise PlanError("unknown block " + dep)
            children[dep].append(b.name)
    return by_name, children, indegree


def erection_order(blocks):
    """Return block names in an order that respects what rests on what."""
    by_name, children, indegree = build_graph(blocks)
    queue = deque(n for n, d in indegree.items() if d == 0)
    order = []
    while queue:
        name = queue.popleft()
        order.append(name)
        for child in children[name]:
            indegree[child] -= 1
            if indegree[child] == 0:
                queue.append(child)
    if len(order) != len(blocks):
        raise PlanError("circular dependency")
    return order


def assign_cranes(blocks, cranes, start=0):
    """Greedy schedule: take blocks in dependency order, give each to the
    crane that becomes free first and is able to lift it.

    Returns a list of (block name, crane name, start hour, end hour).
    """
    by_name, children, indegree = build_graph(blocks)
    done_at = {}
    ready = []
    for n, d in indegree.items():
        if d == 0:
            heapq.heappush(ready, (by_name[n].weight_t, n))
    schedule = []
    for c in cranes:
        c.free_at = start

    while ready:
        weight, name = heapq.heappop(ready)
        block = by_name[name]
        usable = [c for c in cranes if c.can_lift(block)]
        if not usable:
            raise PlanError("no crane can lift " + name)
        crane = min(usable, key=lambda c: c.free_at)
        earliest = max([done_at[d] for d in block.rests_on] + [crane.free_at])
        end = earliest + block.hours
        crane.free_at = end
        done_at[name] = end
        schedule.append((name, crane.name, earliest, end))
        for child in children[name]:
            indegree[child] -= 1
            if indegree[child] == 0:
                heapq.heappush(ready, (by_name[child].weight_t, child))
    return schedule


def total_duration(schedule):
    if not schedule:
        return 0
    return max(end for _, _, _, end in schedule) - min(s for _, _, s, _ in schedule)


def critical_path(blocks):
    """Longest chain of dependent lifts, measured in hours."""
    by_name, children, indegree = build_graph(blocks)
    best = {}
    for name in erection_order(blocks):
        block = by_name[name]
        prior = max([best[d][0] for d in block.rests_on], default=0)
        via = None
        for d in block.rests_on:
            if best[d][0] == prior:
                via = d
        best[name] = (prior + block.hours, via)
    end = max(best, key=lambda n: best[n][0])
    path = [end]
    while best[path[-1]][1] is not None:
        path.append(best[path[-1]][1])
    return list(reversed(path)), best[end][0]


def overweight_report(blocks, cranes):
    """List blocks that no crane can lift, with the heaviest crane capacity."""
    lines = []
    for b in blocks:
        if not any(c.can_lift(b) for c in cranes):
            best = max(c.capacity_at(b.radius_m) for c in cranes)
            lines.append("%s: %.1f t at %.1f m, best crane %.1f t"
                         % (b.name, b.weight_t, b.radius_m, best))
    return lines


if __name__ == "__main__":
    blocks = [
        Block("keel-1", 85, 20, 6),
        Block("keel-2", 90, 20, 6, ["keel-1"]),
        Block("bottom-p", 60, 28, 5, ["keel-1"]),
        Block("bottom-s", 60, 28, 5, ["keel-1"]),
        Block("engine-room", 140, 22, 9, ["keel-2", "bottom-p", "bottom-s"]),
    ]
    cranes = [
        Crane("Goliath", [(15, 200), (25, 150), (35, 90)]),
        Crane("Mobile", [(10, 80), (20, 60), (30, 40)]),
    ]
    for row in assign_cranes(blocks, cranes):
        print(row)
    print(critical_path(blocks))
```

Can you explain what each part of this TypeScript file does, suggest how to refactor it, and write tests for it? It's from our fault-tracking tool at Brightway Lighting, the contractor that maintains the street lights for three councils. Fault reports come in from residents and from sensors, and this module decides priority, the repair deadline and which crew gets the job. I'd like to understand it well enough to change the contract rules without breaking anything.

```typescript
export type FaultKind = "lamp-out" | "flicker" | "column-down" | "exposed-wire" | "cabinet";

export interface Fault {
  id: string;
  kind: FaultKind;
  councilId: string;
  road: string;
  reportedAt: Date;
  lat: number;
  lon: number;
  source: "resident" | "sensor" | "police";
  duplicates: number;
}

export interface Crew {
  id: string;
  name: string;
  hasLiftingPlatform: boolean;
  lat: number;
  lon: number;
  jobsToday: number;
  onCall: boolean;
}

export interface ContractTerms {
  councilId: string;
  hoursByKind: Partial<Record<FaultKind, number>>;
  nightPenaltyPerHour: number;
  maxJobsPerCrew: number;
}

const HIGH_RISK: FaultKind[] = ["exposed-wire", "column-down"];

export function priority(f: Fault): number {
  let score = 0;
  if (HIGH_RISK.includes(f.kind)) score += 100;
  if (f.kind === "cabinet") score += 40;
  if (f.kind === "lamp-out") score += 20;
  if (f.kind === "flicker") score += 5;
  if (f.source === "police") score += 30;
  score += Math.min(f.duplicates, 5) * 3;
  return score;
}

export function deadline(f: Fault, terms: ContractTerms): Date {
  const hours = terms.hoursByKind[f.kind] || 72;
  return new Date(f.reportedAt.getTime() + hours * 3600 * 1000);
}

export function isNight(d: Date): boolean {
  const h = d.getHours();
  return h >= 21 || h < 6;
}

export function penalty(f: Fault, repairedAt: Date, terms: ContractTerms): number {
  const due = deadline(f, terms);
  if (repairedAt <= due) return 0;
  const lateHours = Math.ceil((repairedAt.getTime() - due.getTime()) / 3600000);
  let amount = lateHours * 4;
  if (isNight(f.reportedAt)) {
    amount += lateHours * terms.nightPenaltyPerHour;
  }
  if (HIGH_RISK.includes(f.kind)) amount *= 3;
  return amount;
}

function km(aLat: number, aLon: number, bLat: number, bLon: number): number {
  const dx = (aLon - bLon) * 111 * Math.cos((aLat * Math.PI) / 180);
  const dy = (aLat - bLat) * 111;
  return Math.sqrt(dx * dx + dy * dy);
}

export function pickCrew(
  f: Fault,
  crews: Crew[],
  terms: ContractTerms
): Crew | null {
  const needsPlatform = f.kind === "column-down" || f.kind === "cabinet";
  const candidates = crews.filter((c) => {
    if (c.jobsToday >= terms.maxJobsPerCrew) return false;
    if (needsPlatform && !c.hasLiftingPlatform) return false;
    if (isNight(new Date()) && !c.onCall) return false;
    return true;
  });
  if (candidates.length === 0) return null;
  candidates.sort(
    (a, b) => km(a.lat, a.lon, f.lat, f.lon) - km(b.lat, b.lon, f.lat, f.lon)
  );
  return candidates[0];
}

export function groupNearby(faults: Fault[], radiusKm = 0.3): Fault[][] {
  const groups: Fault[][] = [];
  for (const f of faults) {
    let placed = false;
    for (const g of groups) {
      const first = g[0];
      if (
        first.councilId === f.councilId &&
        km(first.lat, first.lon, f.lat, f.lon) <= radiusKm
      ) {
        g.push(f);
        placed = true;
        break;
      }
    }
    if (!placed) groups.push([f]);
  }
  return groups;
}

export function mergeDuplicate(existing: Fault[], incoming: Fault): Fault[] {
  const match = existing.find(
    (e) =>
      e.kind === incoming.kind &&
      e.road === incoming.road &&
      km(e.lat, e.lon, incoming.lat, incoming.lon) < 0.05
  );
  if (match) {
    match.duplicates++;
    return existing;
  }
  return [...existing, incoming];
}

export function workList(
  faults: Fault[],
  crews: Crew[],
  contracts: Map<string, ContractTerms>
): { fault: Fault; crew: Crew | null; due: Date }[] {
  const ordered = [...faults].sort((a, b) => priority(b) - priority(a));
  const result = [];
  for (const f of ordered) {
    const terms = contracts.get(f.councilId);
    if (!terms) continue;
    const crew = pickCrew(f, crews, terms);
    if (crew) crew.jobsToday++;
    result.push({ fault: f, crew, due: deadline(f, terms) });
  }
  return result;
}

export function monthlyPenaltyTotal(
  repairs: { fault: Fault; repairedAt: Date }[],
  contracts: Map<string, ContractTerms>
): number {
  let total = 0;
  for (const r of repairs) {
    const terms = contracts.get(r.fault.councilId);
    if (terms) total += penalty(r.fault, r.repairedAt, terms);
  }
  return total;
}

export function overdueByCouncil(
  faults: Fault[],
  contracts: Map<string, ContractTerms>,
  now: Date
): Record<string, { open: number; overdue: number }> {
  const out: Record<string, { open: number; overdue: number }> = {};
  for (const f of faults) {
    const terms = contracts.get(f.councilId);
    if (!out[f.councilId]) out[f.councilId] = { open: 0, overdue: 0 };
    out[f.councilId].open++;
    if (terms && deadline(f, terms) < now) out[f.councilId].overdue++;
  }
  return out;
}
