Below is the scheduling module our maintenance crew at the Highmoor wind farm uses to decide which turbines to visit each day. It works, but nobody on the team fully understands it any more. Could you explain what each part does, propose a sensible refactoring (I think it does too much in one place), and write tests for it? I would use Vitest, but any clear test approach is fine.

```ts
// scheduler.ts - daily turbine service planning for the Highmoor wind farm

export type Severity = "info" | "minor" | "major" | "critical";

export interface Turbine {
  id: string;
  name: string;
  ratedKw: number;
  lat: number;
  lon: number;
  lastServiceAt: Date;
  serviceIntervalDays: number;
  needsCrane: boolean;
}

export interface Alarm {
  turbineId: string;
  code: string;
  severity: Severity;
  raisedAt: Date;
  clearedAt?: Date;
}

export interface Technician {
  id: string;
  name: string;
  certifications: string[];
  maxHoursPerDay: number;
  baseLat: number;
  baseLon: number;
}

export interface WindForecast {
  date: string; // YYYY-MM-DD
  maxGustMs: number;
  avgSpeedMs: number;
  lightning: boolean;
}

export interface Job {
  turbineId: string;
  kind: "inspection" | "repair" | "scheduled";
  priority: number;
  estimatedHours: number;
  requiredCert: string;
  reason: string;
}

export interface Assignment {
  technicianId: string;
  turbineId: string;
  startOffsetHours: number;
  job: Job;
}

export interface DayPlan {
  date: string;
  assignments: Assignment[];
  deferred: { job: Job; why: string }[];
}

const SEVERITY_WEIGHT: Record<Severity, number> = {
  info: 1,
  minor: 3,
  major: 8,
  critical: 20,
};

const DAY_MS = 24 * 60 * 60 * 1000;
const GUST_LIMIT_CLIMB = 12;
const AVG_LIMIT_CLIMB = 9;

export function distanceKm(aLat: number, aLon: number, bLat: number, bLon: number): number {
  const toRad = (d: number) => (d * Math.PI) / 180;
  const R = 6371;
  const dLat = toRad(bLat - aLat);
  const dLon = toRad(bLon - aLon);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(toRad(aLat)) * Math.cos(toRad(bLat)) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(h));
}

export function daysOverdue(t: Turbine, today: Date): number {
  const due = t.lastServiceAt.getTime() + t.serviceIntervalDays * DAY_MS;
  return Math.floor((today.getTime() - due) / DAY_MS);
}

export function openAlarms(alarms: Alarm[], turbineId: string): Alarm[] {
  return alarms.filter((a) => a.turbineId === turbineId && !a.clearedAt);
}

export function alarmScore(alarms: Alarm[]): number {
  let score = 0;
  for (const a of alarms) {
    score += SEVERITY_WEIGHT[a.severity];
  }
  return score;
}

export function buildJobs(turbines: Turbine[], alarms: Alarm[], today: Date): Job[] {
  const jobs: Job[] = [];
  for (const t of turbines) {
    const open = openAlarms(alarms, t.id);
    const score = alarmScore(open);
    const overdue = daysOverdue(t, today);

    if (open.some((a) => a.severity === "critical")) {
      jobs.push({
        turbineId: t.id,
        kind: "repair",
        priority: 100 + score,
        estimatedHours: t.needsCrane ? 8 : 5,
        requiredCert: "hv-electrical",
        reason: `critical alarm ${open.find((a) => a.severity === "critical")!.code}`,
      });
    } else if (score >= 8) {
      jobs.push({
        turbineId: t.id,
        kind: "inspection",
        priority: 50 + score,
        estimatedHours: 3,
        requiredCert: "rope-access",
        reason: `${open.length} open alarms, score ${score}`,
      });
    }

    if (overdue >= 0) {
      jobs.push({
        turbineId: t.id,
        kind: "scheduled",
        priority: 20 + Math.min(overdue, 60) / 2,
        estimatedHours: t.ratedKw > 3000 ? 6 : 4,
        requiredCert: "rope-access",
        reason: overdue === 0 ? "service due today" : `service ${overdue} days overdue`,
      });
    }
  }
  return jobs.sort((a, b) => b.priority - a.priority);
}

export function weatherAllows(job: Job, forecast: WindForecast): string | null {
  if (forecast.lightning) return "lightning forecast";
  const needsClimb = job.requiredCert === "rope-access" || job.kind === "repair";
  if (needsClimb && forecast.maxGustMs > GUST_LIMIT_CLIMB) {
    return `gusts ${forecast.maxGustMs} m/s over climbing limit`;
  }
  if (needsClimb && forecast.avgSpeedMs > AVG_LIMIT_CLIMB) {
    return `mean wind ${forecast.avgSpeedMs} m/s over climbing limit`;
  }
  return null;
}

export function planDay(
  date: string,
  jobs: Job[],
  turbines: Turbine[],
  technicians: Technician[],
  forecast: WindForecast,
): DayPlan {
  const plan: DayPlan = { date, assignments: [], deferred: [] };
  const hoursUsed = new Map<string, number>();
  const turbineById = new Map(turbines.map((t) => [t.id, t]));
  const busyTurbines = new Set<string>();

  for (const job of jobs) {
    const weather = weatherAllows(job, forecast);
    if (weather) {
      plan.deferred.push({ job, why: weather });
      continue;
    }
    if (busyTurbines.has(job.turbineId)) {
      plan.deferred.push({ job, why: "turbine already has a job today" });
      continue;
    }
    const turbine = turbineById.get(job.turbineId);
    if (!turbine) {
      plan.deferred.push({ job, why: "unknown turbine" });
      continue;
    }

    const candidates = technicians
      .filter((tech) => tech.certifications.includes(job.requiredCert))
      .filter((tech) => (hoursUsed.get(tech.id) ?? 0) + job.estimatedHours <= tech.maxHoursPerDay);

    if (candidates.length === 0) {
      plan.deferred.push({ job, why: "no certified technician with enough hours" });
      continue;
    }

    candidates.sort((a, b) => {
      const da = distanceKm(a.baseLat, a.baseLon, turbine.lat, turbine.lon);
      const db = distanceKm(b.baseLat, b.baseLon, turbine.lat, turbine.lon);
      return da - db;
    });

    const chosen = candidates[0];
    const start = hoursUsed.get(chosen.id) ?? 0;
    plan.assignments.push({
      technicianId: chosen.id,
      turbineId: job.turbineId,
      startOffsetHours: start,
      job,
    });
    hoursUsed.set(chosen.id, start + job.estimatedHours);
    busyTurbines.add(job.turbineId);
  }
  return plan;
}

export function formatPlan(plan: DayPlan, technicians: Technician[]): string {
  const names = new Map(technicians.map((t) => [t.id, t.name]));
  const lines: string[] = [`Plan for ${plan.date}`];
  if (plan.assignments.length === 0) {
    lines.push("  no work scheduled");
  }
  for (const a of plan.assignments) {
    const start = 7 + a.startOffsetHours;
    const hh = String(Math.floor(start)).padStart(2, "0");
    const mm = String(Math.round((start % 1) * 60)).padStart(2, "0");
    lines.push(
      `  ${hh}:${mm} ${names.get(a.technicianId) ?? a.technicianId} -> ${a.turbineId}: ${a.job.kind} (${a.job.reason})`,
    );
  }
  for (const d of plan.deferred) {
    lines.push(`  deferred ${d.job.turbineId} ${d.job.kind}: ${d.why}`);
  }
  return lines.join("\n");
}

export function planWeek(
  startDate: Date,
  turbines: Turbine[],
  alarms: Alarm[],
  technicians: Technician[],
  forecasts: WindForecast[],
): DayPlan[] {
  const plans: DayPlan[] = [];
  for (let i = 0; i < forecasts.length; i++) {
    const day = new Date(startDate.getTime() + i * DAY_MS);
    const jobs = buildJobs(turbines, alarms, day);
    plans.push(planDay(forecasts[i].date, jobs, turbines, technicians, forecasts[i]));
  }
  return plans;
}

export interface WeekSummary {
  totalAssignments: number;
  totalDeferred: number;
  hoursByTechnician: Record<string, number>;
  deferredByReason: Record<string, number>;
  repeatedDeferrals: string[];
}

export function summariseWeek(plans: DayPlan[]): WeekSummary {
  const summary: WeekSummary = {
    totalAssignments: 0,
    totalDeferred: 0,
    hoursByTechnician: {},
    deferredByReason: {},
    repeatedDeferrals: [],
  };
  const deferralCount = new Map<string, number>();

  for (const plan of plans) {
    summary.totalAssignments += plan.assignments.length;
    summary.totalDeferred += plan.deferred.length;

    for (const a of plan.assignments) {
      const prev = summary.hoursByTechnician[a.technicianId] ?? 0;
      summary.hoursByTechnician[a.technicianId] = prev + a.job.estimatedHours;
    }
    for (const d of plan.deferred) {
      summary.deferredByReason[d.why] = (summary.deferredByReason[d.why] ?? 0) + 1;
      const key = `${d.job.turbineId}:${d.job.kind}`;
      deferralCount.set(key, (deferralCount.get(key) ?? 0) + 1);
    }
  }

  for (const [key, count] of deferralCount) {
    if (count >= 3) summary.repeatedDeferrals.push(key);
  }
  summary.repeatedDeferrals.sort();
  return summary;
}

export function craneJobs(plan: DayPlan, turbines: Turbine[]): string[] {
  const needsCrane = new Set(turbines.filter((t) => t.needsCrane).map((t) => t.id));
  return plan.assignments
    .filter((a) => needsCrane.has(a.turbineId) && a.job.kind === "repair")
    .map((a) => a.turbineId);
}

export function nearestTurbines(from: Turbine, turbines: Turbine[], count: number): Turbine[] {
  return turbines
    .filter((t) => t.id !== from.id)
    .map((t) => ({ t, d: distanceKm(from.lat, from.lon, t.lat, t.lon) }))
    .sort((x, y) => x.d - y.d)
    .slice(0, count)
    .map((x) => x.t);
}

export function utilisation(plan: DayPlan, technicians: Technician[]): Record<string, number> {
  const result: Record<string, number> = {};
  for (const tech of technicians) {
    const hours = plan.assignments
      .filter((a) => a.technicianId === tech.id)
      .reduce((sum, a) => sum + a.job.estimatedHours, 0);
    result[tech.id] = tech.maxHoursPerDay === 0 ? 0 : hours / tech.maxHoursPerDay;
  }
  return result;
}
```

Some background for the review. Technicians start their shift at 07:00 and the farm has 24 turbines; on a normal day we have four technicians, but two of them hold the high-voltage certificate. A turbine needing a crane cannot be worked on if the crane contractor has not been booked, but the module does not know about that and the planners handle it by hand. We have had two complaints from the crew: that the plan sends one person to a distant turbine while another technician sits closer, and that a job planned for a Monday appears again, unchanged, on Tuesday when it was not completed, which they say makes the weekly plan look much busier than it is. I would like to know whether either complaint is a bug in this code or a design choice that should change.

This is the pick-wave planner we use at the Dunmore distribution warehouse to group customer orders into waves for the pickers. It was written quickly by a contractor, and since then several people have patched it. Could you do a thorough code review (bugs, edge cases, design, performance) and then write a complete set of unit tests with pytest? Please say clearly which problems could cause a wrong pick or a lost order, because those matter most to us.

```python
"""Pick-wave planning for the Dunmore warehouse."""

from __future__ import annotations

import heapq
import math
from collections import defaultdict
from dataclasses import dataclass, field
from datetime import datetime, timedelta
from typing import Dict, Iterable, List, Optional, Tuple

AISLE_WIDTH_M = 3.0
BAY_DEPTH_M = 1.2
MAX_WAVE_LINES = 120
MAX_WAVE_WEIGHT_KG = 600.0
MAX_ORDERS_PER_WAVE = 25
CUTOFF_HOUR = 15


@dataclass
class Location:
    aisle: int
    bay: int
    level: int

    def code(self) -> str:
        return f"A{self.aisle:02d}-B{self.bay:02d}-L{self.level}"


@dataclass
class Sku:
    sku: str
    weight_kg: float
    fragile: bool = False
    hazmat: bool = False
    location: Optional[Location] = None


@dataclass
class OrderLine:
    sku: str
    quantity: int


@dataclass
class Order:
    order_id: str
    customer: str
    lines: List[OrderLine]
    placed_at: datetime
    priority: int = 0
    carrier: str = "standard"


@dataclass
class Wave:
    wave_id: int
    orders: List[Order] = field(default_factory=list)
    line_count: int = 0
    weight_kg: float = 0.0
    carrier: str = "standard"


def parse_location(code: str) -> Location:
    """Parse a code such as 'A03-B12-L2'."""
    parts = code.split("-")
    aisle = int(parts[0][1:])
    bay = int(parts[1][1:])
    level = int(parts[2][1:])
    return Location(aisle, bay, level)


def walking_distance(a: Location, b: Location) -> float:
    """Approximate walking distance in metres between two locations."""
    if a.aisle == b.aisle:
        return abs(a.bay - b.bay) * BAY_DEPTH_M
    across = abs(a.aisle - b.aisle) * AISLE_WIDTH_M
    return across + (a.bay + b.bay) * BAY_DEPTH_M


def order_weight(order: Order, catalogue: Dict[str, Sku]) -> float:
    total = 0.0
    for line in order.lines:
        total += catalogue[line.sku].weight_kg * line.quantity
    return total


def is_due_today(order: Order, now: datetime) -> bool:
    """Orders placed before the cutoff leave today; later ones leave tomorrow."""
    cutoff = now.replace(hour=CUTOFF_HOUR, minute=0, second=0, microsecond=0)
    return order.placed_at <= cutoff


def sort_orders(orders: Iterable[Order]) -> List[Order]:
    return sorted(orders, key=lambda o: (-o.priority, o.placed_at))


def build_waves(
    orders: List[Order],
    catalogue: Dict[str, Sku],
    now: datetime,
) -> List[Wave]:
    """Group orders into waves respecting size, weight and carrier limits."""
    waves: List[Wave] = []
    current: Dict[str, Wave] = {}
    next_id = 1

    for order in sort_orders(orders):
        if not is_due_today(order, now):
            continue

        weight = order_weight(order, catalogue)
        lines = len(order.lines)
        wave = current.get(order.carrier)

        needs_new = (
            wave is None
            or wave.line_count + lines > MAX_WAVE_LINES
            or wave.weight_kg + weight > MAX_WAVE_WEIGHT_KG
            or len(wave.orders) >= MAX_ORDERS_PER_WAVE
        )
        if needs_new:
            wave = Wave(wave_id=next_id, carrier=order.carrier)
            next_id += 1
            waves.append(wave)
            current[order.carrier] = wave

        wave.orders.append(order)
        wave.line_count += lines
        wave.weight_kg += weight

    return waves


def pick_list(wave: Wave, catalogue: Dict[str, Sku]) -> List[Tuple[str, str, int]]:
    """Return (location code, sku, quantity) tuples for a wave in walking order."""
    totals: Dict[str, int] = defaultdict(int)
    for order in wave.orders:
        for line in order.lines:
            totals[line.sku] += line.quantity

    stops = []
    for sku, qty in totals.items():
        item = catalogue[sku]
        loc = item.location
        stops.append((loc.aisle, loc.bay if loc.aisle % 2 == 0 else -loc.bay, loc.code(), sku, qty))

    stops.sort()
    return [(code, sku, qty) for _, _, code, sku, qty in stops]


def route_length(stops: List[Location], start: Optional[Location] = None) -> float:
    """Total walking distance for visiting the stops in the given order."""
    if not stops:
        return 0.0
    position = start or Location(1, 0, 1)
    total = 0.0
    for stop in stops:
        total += walking_distance(position, stop)
        position = stop
    return total


def nearest_neighbour(stops: List[Location], start: Location) -> List[Location]:
    """Greedy route: always walk to the closest remaining stop."""
    remaining = list(stops)
    route = []
    position = start
    while remaining:
        best = min(remaining, key=lambda s: walking_distance(position, s))
        remaining.remove(best)
        route.append(best)
        position = best
    return route


def split_hazmat(wave: Wave, catalogue: Dict[str, Sku]) -> Tuple[Wave, Optional[Wave]]:
    """Move orders containing hazardous goods into their own wave."""
    clean = Wave(wave_id=wave.wave_id, carrier=wave.carrier)
    hazard = Wave(wave_id=wave.wave_id * 1000, carrier=wave.carrier)
    for order in wave.orders:
        target = clean
        for line in order.lines:
            if catalogue[line.sku].hazmat:
                target = hazard
        target.orders.append(order)
        target.line_count += len(order.lines)
        target.weight_kg += order_weight(order, catalogue)
    return clean, (hazard if hazard.orders else None)


class StockLedger:
    """Tracks available stock per SKU and reserves quantities for orders."""

    def __init__(self, opening: Dict[str, int]):
        self.available = dict(opening)
        self.reservations: Dict[str, Dict[str, int]] = {}

    def reserve(self, order: Order) -> bool:
        for line in order.lines:
            if self.available.get(line.sku, 0) < line.quantity:
                return False
        held = {}
        for line in order.lines:
            self.available[line.sku] -= line.quantity
            held[line.sku] = held.get(line.sku, 0) + line.quantity
        self.reservations[order.order_id] = held
        return True

    def release(self, order_id: str) -> None:
        held = self.reservations.pop(order_id, {})
        for sku, qty in held.items():
            self.available[sku] = self.available.get(sku, 0) + qty

    def short_orders(self, orders: Iterable[Order]) -> List[str]:
        short = []
        for order in orders:
            if order.order_id not in self.reservations:
                short.append(order.order_id)
        return short


def allocate(orders: List[Order], ledger: StockLedger) -> Tuple[List[Order], List[Order]]:
    """Reserve stock in priority order. Returns (allocated, backordered)."""
    allocated, backordered = [], []
    for order in sort_orders(orders):
        if ledger.reserve(order):
            allocated.append(order)
        else:
            backordered.append(order)
    return allocated, backordered


def slotting_score(sku: str, history: Dict[str, int], catalogue: Dict[str, Sku]) -> float:
    """Higher scores belong closer to the dispatch door: fast, light items."""
    picks = history.get(sku, 0)
    weight = catalogue[sku].weight_kg
    return picks / math.sqrt(weight + 1)


def suggest_moves(
    history: Dict[str, int],
    catalogue: Dict[str, Sku],
    top: int = 10,
) -> List[Tuple[str, str]]:
    """Suggest moving the busiest SKUs to the lowest-numbered aisles."""
    ranked = sorted(catalogue, key=lambda s: slotting_score(s, history, catalogue), reverse=True)
    moves = []
    for rank, sku in enumerate(ranked[:top]):
        target_aisle = rank // 4 + 1
        current = catalogue[sku].location
        if current and current.aisle > target_aisle:
            moves.append((sku, f"A{target_aisle:02d}"))
    return moves


def late_orders(orders: List[Order], now: datetime, sla_hours: int = 24) -> List[Order]:
    """Orders that have been waiting longer than the service level."""
    limit = timedelta(hours=sla_hours)
    return [o for o in orders if now - o.placed_at > limit]


def top_k_heavy(orders: List[Order], catalogue: Dict[str, Sku], k: int = 5) -> List[Tuple[float, str]]:
    heap: List[Tuple[float, str]] = []
    for order in orders:
        w = order_weight(order, catalogue)
        if len(heap) < k:
            heapq.heappush(heap, (w, order.order_id))
        elif w > heap[0][0]:
            heapq.heapreplace(heap, (w, order.order_id))
    return sorted(heap, reverse=True)

@dataclass
class CountResult:
    location_code: str
    sku: str
    expected: int
    counted: int
    counted_at: datetime

    @property
    def variance(self) -> int:
        return self.counted - self.expected


class CycleCounter:
    """Plans and records cycle counts so every location is counted regularly."""

    def __init__(self, catalogue: Dict[str, Sku], expected: Dict[str, int]):
        self.catalogue = catalogue
        self.expected = dict(expected)
        self.last_counted: Dict[str, datetime] = {}
        self.results: List[CountResult] = []

    def due(self, now: datetime, per_day: int = 40, fast_days: int = 30, slow_days: int = 90,
            history: Optional[Dict[str, int]] = None) -> List[str]:
        """Pick the SKUs to count today: fast movers monthly, others quarterly."""
        history = history or {}
        candidates = []
        for sku in self.catalogue:
            interval = fast_days if history.get(sku, 0) >= 50 else slow_days
            last = self.last_counted.get(sku)
            if last is None:
                candidates.append((datetime.min, sku))
            elif now - last >= timedelta(days=interval):
                candidates.append((last, sku))
        candidates.sort()
        return [sku for _, sku in candidates[:per_day]]

    def record(self, sku: str, counted: int, now: datetime) -> CountResult:
        item = self.catalogue[sku]
        result = CountResult(
            location_code=item.location.code(),
            sku=sku,
            expected=self.expected.get(sku, 0),
            counted=counted,
            counted_at=now,
        )
        self.results.append(result)
        self.last_counted[sku] = now
        if result.variance != 0:
            self.expected[sku] = counted
        return result

    def variance_report(self, threshold: int = 2) -> List[str]:
        lines = []
        for r in self.results:
            if abs(r.variance) >= threshold:
                sign = "+" if r.variance > 0 else ""
                lines.append(f"{r.location_code} {r.sku}: expected {r.expected}, counted {r.counted} ({sign}{r.variance})")
        return lines

    def accuracy(self) -> float:
        if not self.results:
            return 1.0
        exact = sum(1 for r in self.results if r.variance == 0)
        return exact / len(self.results)
```

