This is the school-visit booking package we use at the Kestrel Hill Observatory and Outreach Centre for planetarium shows and telescope evenings. I inherited it from a volunteer and I'd like you to explain what each part does, review it properly (bugs, race conditions, anything that will bite us when the autumn rush of school bookings arrives), and then write table-driven tests for the important functions. If you find real bugs, please show the fix and include a test that would have caught each one.

```go
// Package visits handles bookings of school and public groups for shows at
// the Kestrel Hill Observatory and Outreach Centre.
package visits

import (
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
	"time"
)

// Kind is the type of a show.
type Kind string

const (
	Planetarium Kind = "planetarium"
	Telescope   Kind = "telescope"
	Workshop    Kind = "workshop"
)

// Show is a scheduled event with limited seats.
type Show struct {
	ID       string
	Title    string
	Kind     Kind
	Start    time.Time
	Duration time.Duration
	Capacity int
	// PricePence is the price per paying visitor, in pence.
	PricePence int
}

// Group describes a booking party.
type Group struct {
	Name      string
	Contact   string
	Children  int
	Adults    int
	IsSchool  bool
	Postcode  string
	NeedsStep bool // needs step-free access
}

// Booking is a confirmed reservation.
type Booking struct {
	ID        int
	ShowID    string
	Group     Group
	Seats     int
	CreatedAt time.Time
	Cancelled bool
}

// WaitEntry is a group waiting for a place on a full show.
type WaitEntry struct {
	Group Group
	Seats int
	Added time.Time
}

var (
	ErrNoSuchShow    = errors.New("visits: no such show")
	ErrShowStarted   = errors.New("visits: show has already started")
	ErrInvalidGroup  = errors.New("visits: invalid group")
	ErrFull          = errors.New("visits: not enough seats")
	ErrNoSuchBooking = errors.New("visits: no such booking")
)

// Scheduler keeps shows, bookings and waiting lists in memory.
type Scheduler struct {
	mu       sync.Mutex
	shows    map[string]*Show
	bookings map[int]*Booking
	waiting  map[string][]WaitEntry
	nextID   int
	now      func() time.Time
}

// NewScheduler returns an empty scheduler. If now is nil, time.Now is used.
func NewScheduler(now func() time.Time) *Scheduler {
	if now == nil {
		now = time.Now
	}
	return &Scheduler{
		shows:    make(map[string]*Show),
		bookings: make(map[int]*Booking),
		waiting:  make(map[string][]WaitEntry),
		nextID:   1,
		now:      now,
	}
}

// AddShow registers a show. The ID must be unique and capacity positive.
func (s *Scheduler) AddShow(sh Show) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if sh.ID == "" || sh.Capacity <= 0 {
		return fmt.Errorf("visits: invalid show %q", sh.ID)
	}
	if _, ok := s.shows[sh.ID]; ok {
		return fmt.Errorf("visits: duplicate show %q", sh.ID)
	}
	s.shows[sh.ID] = &sh
	return nil
}

func (g Group) seats() int {
	return g.Children + g.Adults
}

func (g Group) validate() error {
	if strings.TrimSpace(g.Name) == "" {
		return fmt.Errorf("%w: empty name", ErrInvalidGroup)
	}
	if g.Children < 0 || g.Adults < 0 || g.seats() == 0 {
		return fmt.Errorf("%w: no visitors", ErrInvalidGroup)
	}
	if g.IsSchool && g.Adults == 0 {
		return fmt.Errorf("%w: school group needs an adult", ErrInvalidGroup)
	}
	return nil
}

// seatsTaken returns the number of seats in active bookings for a show.
// The caller must hold s.mu.
func (s *Scheduler) seatsTaken(showID string) int {
	n := 0
	for _, b := range s.bookings {
		if b.ShowID == showID && !b.Cancelled {
			n += b.Seats
		}
	}
	return n
}

// Available returns the number of seats left on a show.
func (s *Scheduler) Available(showID string) (int, error) {
	sh, ok := s.shows[showID]
	if !ok {
		return 0, ErrNoSuchShow
	}
	return sh.Capacity - s.seatsTaken(showID), nil
}

// Book reserves seats for a group. If the show is full, ErrFull is returned
// and the caller may call Wait.
func (s *Scheduler) Book(showID string, g Group) (*Booking, error) {
	if err := g.validate(); err != nil {
		return nil, err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	sh, ok := s.shows[showID]
	if !ok {
		return nil, ErrNoSuchShow
	}
	if s.now().After(sh.Start) {
		return nil, ErrShowStarted
	}
	if sh.Capacity-s.seatsTaken(showID) < g.seats() {
		return nil, ErrFull
	}
	b := &Booking{
		ID:        s.nextID,
		ShowID:    showID,
		Group:     g,
		Seats:     g.seats(),
		CreatedAt: s.now(),
	}
	s.nextID++
	s.bookings[b.ID] = b
	return b, nil
}

// Wait puts a group on the waiting list of a full show.
func (s *Scheduler) Wait(showID string, g Group) error {
	if err := g.validate(); err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if _, ok := s.shows[showID]; !ok {
		return ErrNoSuchShow
	}
	s.waiting[showID] = append(s.waiting[showID], WaitEntry{Group: g, Seats: g.seats(), Added: s.now()})
	return nil
}

// Cancel cancels a booking. Groups cancelling less than 48 hours before the
// show start are still charged (see Charge), but the seats are freed and
// offered to the waiting list.
func (s *Scheduler) Cancel(id int) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	b, ok := s.bookings[id]
	if !ok {
		return ErrNoSuchBooking
	}
	b.Cancelled = true
	s.promote(b.ShowID)
	return nil
}

// promote offers freed seats to waiting groups in order. The caller must
// hold s.mu.
func (s *Scheduler) promote(showID string) {
	sh := s.shows[showID]
	q := s.waiting[showID]
	var rest []WaitEntry
	for _, w := range q {
		if sh.Capacity-s.seatsTaken(showID) >= w.Seats {
			b := &Booking{
				ID:        s.nextID,
				ShowID:    showID,
				Group:     w.Group,
				Seats:     w.Seats,
				CreatedAt: s.now(),
			}
			s.nextID++
			s.bookings[b.ID] = b
		} else {
			rest = append(rest, w)
		}
	}
	s.waiting[showID] = rest
}

// Charge returns the amount owed in pence for a booking.
//
// Rules: school groups get one free adult for every 10 children, and every
// other adult pays full price. Children in school groups pay 80% of the show
// price. Public groups of 10 or more seats get 10% off the whole booking.
// A late cancellation (under 48 hours before the start) is charged 50% of
// what the booking would have cost.
func (s *Scheduler) Charge(id int) (int, error) {
	s.mu.Lock()
	b, ok := s.bookings[id]
	if !ok {
		s.mu.Unlock()
		return 0, ErrNoSuchBooking
	}
	sh := s.shows[b.ShowID]
	s.mu.Unlock()

	g := b.Group
	var total float64
	if g.IsSchool {
		freeAdults := g.Children / 10
		payingAdults := g.Adults - freeAdults
		if payingAdults < 0 {
			payingAdults = 0
		}
		total = float64(g.Children)*float64(sh.PricePence)*0.8 +
			float64(payingAdults)*float64(sh.PricePence)
	} else {
		total = float64(g.seats()) * float64(sh.PricePence)
		if g.seats() >= 10 {
			total = total * 0.9
		}
	}
	if b.Cancelled {
		if sh.Start.Sub(b.CreatedAt) < 48*time.Hour {
			total = total * 0.5
		} else {
			total = 0
		}
	}
	return int(total), nil
}

// DayReport lists, for each show starting on the given date, the title,
// seats booked and the income in pence.
func (s *Scheduler) DayReport(day time.Time) []string {
	var lines []string
	for _, sh := range s.shows {
		if sh.Start.Year() == day.Year() && sh.Start.YearDay() == day.YearDay() {
			income := 0
			for id, b := range s.bookings {
				if b.ShowID == sh.ID && !b.Cancelled {
					c, _ := s.Charge(id)
					income += c
				}
			}
			lines = append(lines, fmt.Sprintf("%s: %d/%d seats, %d.%02d pounds",
				sh.Title, s.seatsTaken(sh.ID), sh.Capacity, income/100, income%100))
		}
	}
	sort.Strings(lines)
	return lines
}

// AddVisitors adds children and adults to an existing booking if the show
// has room, and returns the updated booking.
func (s *Scheduler) AddVisitors(id, children, adults int) (*Booking, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	b, ok := s.bookings[id]
	if !ok || b.Cancelled {
		return nil, ErrNoSuchBooking
	}
	extra := children + adults
	if extra <= 0 {
		return nil, fmt.Errorf("%w: nothing to add", ErrInvalidGroup)
	}
	sh := s.shows[b.ShowID]
	if s.now().After(sh.Start) {
		return nil, ErrShowStarted
	}
	if sh.Capacity-s.seatsTaken(b.ShowID) < extra {
		return nil, ErrFull
	}
	b.Group.Children += children
	b.Group.Adults += adults
	b.Seats += extra
	return b, nil
}

// WaitingSeats returns the number of seats requested by each group on the
// waiting list of a show, in the order they joined.
func (s *Scheduler) WaitingSeats(showID string) []int {
	s.mu.Lock()
	defer s.mu.Unlock()
	var out []int
	for _, w := range s.waiting[showID] {
		out = append(out, w.Seats)
	}
	return out
}

// StepFreeSeats returns the number of seats booked by groups that need
// step-free access, across all shows of the given kind.
func (s *Scheduler) StepFreeSeats(kind Kind) int {
	s.mu.Lock()
	defer s.mu.Unlock()
	n := 0
	for _, b := range s.bookings {
		if b.Group.NeedsStep && s.shows[b.ShowID].Kind == kind {
			n += b.Seats
		}
	}
	return n
}
```

A few notes from the person who used to maintain it: "Late cancellation" is meant to be measured from the moment of cancellation to the start of the show, not from when the booking was made, and I'm not sure the code does that. Schools sometimes ring up to add two or three children to an existing booking, and today we just cancel and rebook, which loses their place in the queue. The dashboard calls `DayReport` every few seconds while the bookings team are also taking bookings by phone. Our shows run in the local time of the centre, so there are two evenings a year when the clocks change. Finally, the planetarium dome has 60 seats but only 4 wheelchair spaces, and nothing in the code checks that.

This is the module we use at Lakeside Aquatics to book lane sessions, check water quality readings and work out the lifeguard cover for each day. It works, but I wrote it quickly and I don't trust it. Please review it properly (bugs, edge cases, design problems, anything that could cause a safety or billing mistake) and then write a full set of unit tests with pytest that covers the behaviour you think is correct.

```python
"""poolops.py - session booking, water quality checks and lifeguard cover
for the Lakeside Aquatics public pools.

Times are naive local times; the site operates in one time zone.
"""

from __future__ import annotations

import csv
import io
import math
from dataclasses import dataclass, field
from datetime import date, datetime, time, timedelta
from typing import Dict, Iterable, List, Optional, Tuple

# ---------------------------------------------------------------------------
# Constants
# ---------------------------------------------------------------------------

OPENING_TIME = time(6, 30)
CLOSING_TIME = time(21, 30)
SLOT_MINUTES = 30
MAX_LANES = 8
SWIMMERS_PER_LANE = 12
LEISURE_POOL_CAPACITY = 90
GUARD_RATIO_LANES = 40      # one guard per 40 swimmers in the lane pool
GUARD_RATIO_LEISURE = 30    # one guard per 30 swimmers in the leisure pool
MIN_GUARDS = 2

CHLORINE_MIN = 1.0   # mg/l free chlorine
CHLORINE_MAX = 3.0
PH_MIN = 7.2
PH_MAX = 7.8
TEMP_MIN = 26.0      # degrees Celsius
TEMP_MAX = 32.0

PRICES = {
    "adult": 5.80,
    "child": 3.20,
    "senior": 3.90,
    "concession": 3.50,
}
MEMBER_DISCOUNT = 0.15
FAMILY_BUNDLE_PRICE = 14.00


# ---------------------------------------------------------------------------
# Data classes
# ---------------------------------------------------------------------------

@dataclass
class Booking:
    booking_id: str
    customer: str
    day: date
    start: time
    slots: int
    lanes: int
    category: str = "adult"
    member: bool = False
    cancelled: bool = False

    def end_time(self) -> time:
        start_dt = datetime.combine(self.day, self.start)
        return (start_dt + timedelta(minutes=SLOT_MINUTES * self.slots)).time()


@dataclass
class WaterReading:
    taken_at: datetime
    pool: str
    chlorine: float
    ph: float
    temperature: float
    taken_by: str = ""


@dataclass
class Guard:
    name: str
    certified_until: date
    available_days: List[int] = field(default_factory=list)  # 0 = Monday


# ---------------------------------------------------------------------------
# Booking
# ---------------------------------------------------------------------------

class BookingError(Exception):
    pass


class LaneCalendar:
    """Keeps track of how many lanes are taken in each half hour slot."""

    def __init__(self) -> None:
        self.bookings: Dict[str, Booking] = {}
        self.usage: Dict[Tuple[date, time], int] = {}

    def _slots_for(self, day: date, start: time, slots: int) -> List[Tuple[date, time]]:
        result = []
        current = datetime.combine(day, start)
        for _ in range(slots):
            result.append((current.date(), current.time()))
            current += timedelta(minutes=SLOT_MINUTES)
        return result

    def lanes_free(self, day: date, start: time, slots: int) -> int:
        taken = 0
        for key in self._slots_for(day, start, slots):
            taken = max(taken, self.usage.get(key, 0))
        return MAX_LANES - taken

    def add(self, booking: Booking) -> None:
        if booking.booking_id in self.bookings:
            raise BookingError("duplicate booking id " + booking.booking_id)
        if booking.start < OPENING_TIME:
            raise BookingError("before opening time")
        if booking.end_time() > CLOSING_TIME:
            raise BookingError("after closing time")
        if booking.lanes < 1:
            raise BookingError("at least one lane is required")
        if self.lanes_free(booking.day, booking.start, booking.slots) < booking.lanes:
            raise BookingError("not enough lanes free")
        for key in self._slots_for(booking.day, booking.start, booking.slots):
            self.usage[key] = self.usage.get(key, 0) + booking.lanes
        self.bookings[booking.booking_id] = booking

    def cancel(self, booking_id: str) -> Booking:
        booking = self.bookings.get(booking_id)
        if booking is None:
            raise BookingError("unknown booking " + booking_id)
        booking.cancelled = True
        for key in self._slots_for(booking.day, booking.start, booking.slots):
            self.usage[key] -= booking.lanes
        return booking

    def bookings_on(self, day: date) -> List[Booking]:
        found = [b for b in self.bookings.values() if b.day == day and not b.cancelled]
        return sorted(found, key=lambda b: b.start)

    def peak_usage(self, day: date) -> int:
        values = [v for (d, _), v in self.usage.items() if d == day]
        return max(values) if values else 0


# ---------------------------------------------------------------------------
# Pricing
# ---------------------------------------------------------------------------

def price_for_swimmer(category: str, member: bool = False) -> float:
    if category not in PRICES:
        raise ValueError("unknown category: " + category)
    price = PRICES[category]
    if member:
        price = price * (1 - MEMBER_DISCOUNT)
    return round(price, 2)


def price_for_group(categories: Iterable[str], member: bool = False) -> float:
    """Price for a group entering together.

    Two adults and two or more children qualify for the family bundle.
    """
    cats = list(categories)
    adults = cats.count("adult")
    children = cats.count("child")
    others = [c for c in cats if c not in ("adult", "child")]

    total = 0.0
    if adults >= 2 and children >= 2:
        total += FAMILY_BUNDLE_PRICE
        adults -= 2
        children -= 2
    for _ in range(adults):
        total += price_for_swimmer("adult", member)
    for _ in range(children):
        total += price_for_swimmer("child", member)
    for c in others:
        total += price_for_swimmer(c, member)
    return round(total, 2)


def lane_session_fee(booking: Booking, hourly_rate: float = 24.0) -> float:
    """Fee for a club or group booking of lanes."""
    hours = booking.slots * SLOT_MINUTES / 60
    fee = hourly_rate * hours * booking.lanes
    if booking.member:
        fee *= 1 - MEMBER_DISCOUNT
    return round(fee, 2)


# ---------------------------------------------------------------------------
# Water quality
# ---------------------------------------------------------------------------

def check_reading(reading: WaterReading) -> List[str]:
    """Return a list of problems found in a reading; empty means all good."""
    problems = []
    if reading.chlorine < CHLORINE_MIN:
        problems.append("chlorine too low")
    if reading.chlorine > CHLORINE_MAX:
        problems.append("chlorine too high")
    if reading.ph < PH_MIN:
        problems.append("pH too low")
    if reading.ph > PH_MAX:
        problems.append("pH too high")
    if reading.temperature < TEMP_MIN:
        problems.append("water too cold")
    if reading.temperature > TEMP_MAX:
        problems.append("water too warm")
    return problems


def pool_must_close(reading: WaterReading) -> bool:
    """A pool closes if chlorine is out of range or pH is out of range."""
    problems = check_reading(reading)
    return any("chlorine" in p or "pH" in p for p in problems)


def readings_overdue(readings: List[WaterReading], pool: str, now: datetime,
                     interval_hours: int = 2) -> bool:
    """True if no reading has been taken for the pool in the last interval."""
    latest = None
    for r in readings:
        if r.pool == pool and (latest is None or r.taken_at > latest):
            latest = r.taken_at
    if latest is None:
        return True
    return now - latest > timedelta(hours=interval_hours)


def chlorine_dose_grams(volume_m3: float, current: float, target: float,
                        grams_per_m3_per_mgl: float = 1.8) -> float:
    """Grams of chlorine granules needed to raise the level to the target."""
    if target <= current:
        return 0.0
    return round(volume_m3 * (target - current) * grams_per_m3_per_mgl, 1)


def daily_summary(readings: List[WaterReading], day: date) -> Dict[str, float]:
    day_readings = [r for r in readings if r.taken_at.date() == day]
    if not day_readings:
        return {}
    n = len(day_readings)
    return {
        "count": n,
        "chlorine_avg": round(sum(r.chlorine for r in day_readings) / n, 2),
        "ph_avg": round(sum(r.ph for r in day_readings) / n, 2),
        "temp_avg": round(sum(r.temperature for r in day_readings) / n, 1),
        "out_of_range": sum(1 for r in day_readings if check_reading(r)),
    }


# ---------------------------------------------------------------------------
# Lifeguard cover
# ---------------------------------------------------------------------------

def guards_required(lane_swimmers: int, leisure_swimmers: int) -> int:
    """Number of lifeguards needed for the expected number of swimmers."""
    lane_guards = math.ceil(lane_swimmers / GUARD_RATIO_LANES)
    leisure_guards = math.ceil(leisure_swimmers / GUARD_RATIO_LEISURE)
    return max(MIN_GUARDS, lane_guards + leisure_guards)


def expected_lane_swimmers(calendar: LaneCalendar, day: date, start: time) -> int:
    lanes_used = MAX_LANES - calendar.lanes_free(day, start, 1)
    return lanes_used * SWIMMERS_PER_LANE


def eligible_guards(guards: List[Guard], day: date) -> List[Guard]:
    return [g for g in guards
            if day.weekday() in g.available_days and g.certified_until >= day]


def cover_gaps(calendar: LaneCalendar, guards: List[Guard], day: date,
               leisure_forecast: int) -> List[Tuple[time, int, int]]:
    """For each half hour, return (slot, required, available) where short."""
    available = len(eligible_guards(guards, day))
    gaps = []
    current = datetime.combine(day, OPENING_TIME)
    end = datetime.combine(day, CLOSING_TIME)
    while current < end:
        lane_swimmers = expected_lane_swimmers(calendar, day, current.time())
        needed = guards_required(lane_swimmers, leisure_forecast)
        if needed > available:
            gaps.append((current.time(), needed, available))
        current += timedelta(minutes=SLOT_MINUTES)
    return gaps


# ---------------------------------------------------------------------------
# Reports
# ---------------------------------------------------------------------------

def bookings_to_csv(bookings: List[Booking]) -> str:
    out = io.StringIO()
    writer = csv.writer(out)
    writer.writerow(["id", "customer", "day", "start", "end", "lanes", "fee"])
    for b in bookings:
        writer.writerow([
            b.booking_id,
            b.customer,
            b.day.isoformat(),
            b.start.strftime("%H:%M"),
            b.end_time().strftime("%H:%M"),
            b.lanes,
            "%.2f" % lane_session_fee(b),
        ])
    return out.getvalue()


def utilisation(calendar: LaneCalendar, day: date) -> float:
    """Share of lane-slots used on a day, as a percentage."""
    total_slots = int(
        (datetime.combine(day, CLOSING_TIME) - datetime.combine(day, OPENING_TIME))
        .total_seconds() / 60 / SLOT_MINUTES
    )
    used = sum(v for (d, _), v in calendar.usage.items() if d == day)
    return round(100.0 * used / (total_slots * MAX_LANES), 1)
```

A few notes on how it is used. The front desk calls `LaneCalendar.add` when a club phones to book lanes, the evening duty manager runs `cover_gaps` every Sunday for the following week, and the pool plant technician enters readings through a small tablet app that calls `check_reading` and `pool_must_close`. The pool must be closed straight away if `pool_must_close` returns true, so I am especially worried about mistakes in that part. The leisure pool is not booked through the calendar at all, only the lane pool. We have not had a billing complaint yet but the finance team says the family bundle looks odd on some Saturdays.

Here is the inventory module from our seed bank's internal tool (Thornfield Seed Vault). Could you explain what each part does in plain terms for a new developer, propose a refactoring that makes it easier to maintain and test, and write the tests (Vitest is fine) for the refactored version? Please point out any place where the current logic could give a wrong answer about whether a seed lot is still usable.

```typescript
// inventory.ts - accessions, storage positions, viability checks and
// regeneration planning for the Thornfield Seed Vault.

export type Species = {
  code: string;            // e.g. "AVE-SAT"
  latinName: string;
  commonName: string;
  storageClass: "orthodox" | "intermediate";
  baselineViability: number; // percent germination expected from fresh seed
  retestIntervalYears: number;
};

export type Accession = {
  id: string;
  speciesCode: string;
  collectedOn: string;      // ISO date
  collectorId: string;
  originCountry: string;
  seedCount: number;
  initialViability: number; // percent
  position?: StoragePosition;
  status: "active" | "depleted" | "regeneration" | "quarantine";
};

export type StoragePosition = {
  freezer: number;
  shelf: number;
  box: number;
};

export type GerminationTest = {
  accessionId: string;
  testedOn: string;         // ISO date
  seedsSown: number;
  seedsGerminated: number;
};

export type Withdrawal = {
  accessionId: string;
  date: string;
  seeds: number;
  requestedBy: string;
  purpose: "research" | "restoration" | "testing" | "duplicate";
};

const DAY_MS = 24 * 60 * 60 * 1000;
const FREEZER_COUNT = 6;
const SHELVES_PER_FREEZER = 8;
const BOXES_PER_SHELF = 20;
const MIN_SEEDS_FOR_ACTIVE = 500;
const REGENERATION_THRESHOLD = 85; // percent of initial viability
const SAFE_VIABILITY_FLOOR = 60;   // absolute percent

export function yearsBetween(from: string, to: string): number {
  const a = new Date(from).getTime();
  const b = new Date(to).getTime();
  return (b - a) / (365 * DAY_MS);
}

export function germinationRate(test: GerminationTest): number {
  if (test.seedsSown === 0) return 0;
  return Math.round((test.seedsGerminated / test.seedsSown) * 1000) / 10;
}

export function latestTest(
  tests: GerminationTest[],
  accessionId: string
): GerminationTest | undefined {
  let latest: GerminationTest | undefined;
  for (const t of tests) {
    if (t.accessionId !== accessionId) continue;
    if (!latest || t.testedOn > latest.testedOn) {
      latest = t;
    }
  }
  return latest;
}

export function seedsRemaining(
  accession: Accession,
  withdrawals: Withdrawal[]
): number {
  let remaining = accession.seedCount;
  for (const w of withdrawals) {
    if (w.accessionId === accession.id) {
      remaining -= w.seeds;
    }
  }
  return remaining;
}

export function isRetestDue(
  accession: Accession,
  species: Species,
  tests: GerminationTest[],
  today: string
): boolean {
  const last = latestTest(tests, accession.id);
  const since = last ? last.testedOn : accession.collectedOn;
  return yearsBetween(since, today) >= species.retestIntervalYears;
}

export function viabilityStatus(
  accession: Accession,
  tests: GerminationTest[]
): "good" | "declining" | "critical" | "unknown" {
  const last = latestTest(tests, accession.id);
  if (!last) return "unknown";
  const rate = germinationRate(last);
  if (rate < SAFE_VIABILITY_FLOOR) return "critical";
  if (rate < accession.initialViability * (REGENERATION_THRESHOLD / 100)) {
    return "declining";
  }
  return "good";
}

export function needsRegeneration(
  accession: Accession,
  species: Species,
  tests: GerminationTest[],
  withdrawals: Withdrawal[]
): boolean {
  if (accession.status === "regeneration") return false;
  const remaining = seedsRemaining(accession, withdrawals);
  if (remaining < MIN_SEEDS_FOR_ACTIVE) return true;
  const status = viabilityStatus(accession, tests);
  return status === "critical" || status === "declining";
}

export function allocatePosition(
  occupied: StoragePosition[],
  storageClass: Species["storageClass"]
): StoragePosition | null {
  // Intermediate seeds go in freezers 5 and 6 only (drier room).
  const freezers =
    storageClass === "intermediate" ? [5, 6] : [1, 2, 3, 4, 5, 6];
  const taken = new Set(
    occupied.map((p) => `${p.freezer}-${p.shelf}-${p.box}`)
  );
  for (const freezer of freezers) {
    for (let shelf = 1; shelf <= SHELVES_PER_FREEZER; shelf++) {
      for (let box = 1; box <= BOXES_PER_SHELF; box++) {
        if (!taken.has(`${freezer}-${shelf}-${box}`)) {
          return { freezer, shelf, box };
        }
      }
    }
  }
  return null;
}

export function formatPosition(p: StoragePosition | undefined): string {
  if (!p) return "unassigned";
  const f = String(p.freezer).padStart(2, "0");
  const s = String(p.shelf).padStart(2, "0");
  const b = String(p.box).padStart(3, "0");
  return `F${f}-S${s}-B${b}`;
}

export function parsePosition(text: string): StoragePosition | null {
  const match = /^F(\d{2})-S(\d{2})-B(\d{3})$/.exec(text);
  if (!match) return null;
  const position = {
    freezer: parseInt(match[1], 10),
    shelf: parseInt(match[2], 10),
    box: parseInt(match[3], 10),
  };
  if (position.freezer > FREEZER_COUNT) return null;
  return position;
}

export type WithdrawalCheck =
  | { ok: true }
  | { ok: false; reason: string };

export function checkWithdrawal(
  accession: Accession,
  withdrawals: Withdrawal[],
  request: Withdrawal
): WithdrawalCheck {
  if (accession.status === "quarantine") {
    return { ok: false, reason: "accession is in quarantine" };
  }
  if (accession.status === "depleted") {
    return { ok: false, reason: "accession is depleted" };
  }
  const remaining = seedsRemaining(accession, withdrawals);
  if (request.seeds <= 0) {
    return { ok: false, reason: "seed count must be positive" };
  }
  if (request.seeds > remaining) {
    return { ok: false, reason: "not enough seeds remaining" };
  }
  // Keep a reserve for the long-term collection unless it is a duplicate
  // being sent to the partner vault.
  const reserve = Math.floor(accession.seedCount * 0.5);
  if (request.purpose !== "duplicate" && remaining - request.seeds < reserve) {
    return { ok: false, reason: "withdrawal would breach the reserve" };
  }
  return { ok: true };
}

export type RegenerationPlanItem = {
  accessionId: string;
  speciesCode: string;
  reason: string;
  targetSeeds: number;
  plantsNeeded: number;
};

export function planRegeneration(
  accessions: Accession[],
  speciesByCode: Map<string, Species>,
  tests: GerminationTest[],
  withdrawals: Withdrawal[],
  seedsPerPlant = 40
): RegenerationPlanItem[] {
  const plan: RegenerationPlanItem[] = [];
  for (const a of accessions) {
    const species = speciesByCode.get(a.speciesCode);
    if (!species) continue;
    if (!needsRegeneration(a, species, tests, withdrawals)) continue;
    const remaining = seedsRemaining(a, withdrawals);
    const status = viabilityStatus(a, tests);
    const reason =
      remaining < MIN_SEEDS_FOR_ACTIVE
        ? `only ${remaining} seeds left`
        : `viability is ${status}`;
    const targetSeeds = Math.max(a.seedCount, 2000);
    const plantsNeeded = Math.ceil(targetSeeds / seedsPerPlant);
    plan.push({
      accessionId: a.id,
      speciesCode: a.speciesCode,
      reason,
      targetSeeds,
      plantsNeeded,
    });
  }
  return plan.sort((x, y) => y.plantsNeeded - x.plantsNeeded);
}

export function summariseByCountry(
  accessions: Accession[]
): Record<string, { accessions: number; seeds: number }> {
  const result: Record<string, { accessions: number; seeds: number }> = {};
  for (const a of accessions) {
    const entry = result[a.originCountry] ?? { accessions: 0, seeds: 0 };
    entry.accessions += 1;
    entry.seeds += a.seedCount;
    result[a.originCountry] = entry;
  }
  return result;
}

export function retestSchedule(
  accessions: Accession[],
  speciesByCode: Map<string, Species>,
  tests: GerminationTest[],
  today: string
): { accessionId: string; dueSinceYears: number }[] {
  const due: { accessionId: string; dueSinceYears: number }[] = [];
  for (const a of accessions) {
    if (a.status !== "active") continue;
    const species = speciesByCode.get(a.speciesCode);
    if (!species) continue;
    if (isRetestDue(a, species, tests, today)) {
      const last = latestTest(tests, a.id);
      const since = last ? last.testedOn : a.collectedOn;
      due.push({
        accessionId: a.id,
        dueSinceYears:
          Math.round(
            (yearsBetween(since, today) - species.retestIntervalYears) * 10
          ) / 10,
      });
    }
  }
  return due.sort((x, y) => y.dueSinceYears - x.dueSinceYears);
}

export type PositionConflict = {
  position: string;
  accessionIds: string[];
};

export function findPositionConflicts(
  accessions: Accession[]
): PositionConflict[] {
  const byPosition = new Map<string, string[]>();
  for (const a of accessions) {
    if (!a.position) continue;
    const key = formatPosition(a.position);
    const list = byPosition.get(key) ?? [];
    list.push(a.id);
    byPosition.set(key, list);
  }
  const conflicts: PositionConflict[] = [];
  for (const [position, accessionIds] of byPosition) {
    if (accessionIds.length > 1) {
      conflicts.push({ position, accessionIds });
    }
  }
  return conflicts.sort((a, b) => a.position.localeCompare(b.position));
}

export type DuplicateManifestLine = {
  accessionId: string;
  latinName: string;
  seeds: number;
  germinationPercent: number | null;
  collectedOn: string;
};

export function buildDuplicateManifest(
  accessions: Accession[],
  speciesByCode: Map<string, Species>,
  tests: GerminationTest[],
  withdrawals: Withdrawal[],
  maxSeedsPerAccession = 250
): DuplicateManifestLine[] {
  const lines: DuplicateManifestLine[] = [];
  for (const a of accessions) {
    if (a.status !== "active") continue;
    const species = speciesByCode.get(a.speciesCode);
    if (!species) continue;
    const alreadySent = withdrawals
      .filter((w) => w.accessionId === a.id && w.purpose === "duplicate")
      .reduce((sum, w) => sum + w.seeds, 0);
    if (alreadySent >= maxSeedsPerAccession) continue;
    const last = latestTest(tests, a.id);
    lines.push({
      accessionId: a.id,
      latinName: species.latinName,
      seeds: Math.min(
        maxSeedsPerAccession - alreadySent,
        seedsRemaining(a, withdrawals)
      ),
      germinationPercent: last ? germinationRate(last) : null,
      collectedOn: a.collectedOn,
    });
  }
  return lines.sort((x, y) => x.latinName.localeCompare(y.latinName));
}

export function releaseFromQuarantine(
  accession: Accession,
  inspectionPassed: boolean,
  occupied: StoragePosition[],
  species: Species
): Accession {
  if (accession.status !== "quarantine") return accession;
  if (!inspectionPassed) {
    return { ...accession, status: "depleted" };
  }
  const position = accession.position ?? allocatePosition(occupied, species.storageClass);
  return {
    ...accession,
    status: "active",
    position: position ?? undefined,
  };
}

export function collectionHealth(
  accessions: Accession[],
  tests: GerminationTest[]
): { good: number; declining: number; critical: number; unknown: number } {
  const counts = { good: 0, declining: 0, critical: 0, unknown: 0 };
  for (const a of accessions) {
    if (a.status === "depleted") continue;
    counts[viabilityStatus(a, tests)] += 1;
  }
  return counts;
}
