```python
"""harbour.py - berth allocation, dues and landing fees for Port Merrow.

Used by the harbour office to allocate berths and to produce the monthly
invoice lines for each vessel.
"""

import csv
import datetime
import io
import math
from collections import defaultdict
from dataclasses import dataclass, field

DUES_PER_GT_PER_DAY = 0.42        # euro per gross tonne per day
MINIMUM_DAILY_DUES = 6.50
NIGHT_SURCHARGE = 0.15            # applied to arrivals between 22:00 and 05:00
LANDING_FEE_RATE = 0.012          # share of landed value
LANDING_FEE_MINIMUM = 4.00
HOME_PORT_DISCOUNT = 0.20
ICE_PRICE_PER_TONNE = 38.0
VAT = 0.21

LENGTH_CLASSES = [(12, "S"), (18, "M"), (30, "L")]


@dataclass
class Vessel:
    reg: str
    name: str
    gross_tonnage: float
    length_m: float
    home_port: str = "Port Merrow"
    species_licences: list = field(default_factory=list)

    def size_class(self):
        for limit, label in LENGTH_CLASSES:
            if self.length_m < limit:
                return label
        return "XL"


@dataclass
class Berth:
    code: str
    max_length_m: float
    max_draught_m: float
    has_power: bool = False
    occupied_by: str = None


@dataclass
class Stay:
    vessel: Vessel
    berth_code: str
    arrival: datetime.datetime
    departure: datetime.datetime = None


@dataclass
class Landing:
    vessel_reg: str
    species: str
    weight_kg: float
    price_per_kg: float
    when: datetime.date

    @property
    def value(self):
        return self.weight_kg * self.price_per_kg


class AllocationError(Exception):
    pass


class Harbour:
    def __init__(self, berths, ice_sales=[]):
        self.berths = {b.code: b for b in berths}
        self.stays = []
        self.landings = []
        self.ice_sales = ice_sales

    # ---- berth allocation -------------------------------------------------

    def free_berths(self):
        return [b for b in self.berths.values() if b.occupied_by is None]

    def find_berth(self, vessel, draught_m, needs_power=False):
        candidates = []
        for berth in self.free_berths():
            if berth.max_length_m < vessel.length_m:
                continue
            if berth.max_draught_m < draught_m:
                continue
            if needs_power and not berth.has_power:
                continue
            candidates.append(berth)
        if not candidates:
            raise AllocationError("no berth for %s" % vessel.reg)
        # smallest berth that fits, so the big ones stay free
        candidates.sort(key=lambda b: b.max_length_m)
        return candidates[0]

    def arrive(self, vessel, draught_m, when, needs_power=False):
        berth = self.find_berth(vessel, draught_m, needs_power)
        berth.occupied_by = vessel.reg
        stay = Stay(vessel, berth.code, when)
        self.stays.append(stay)
        return stay

    def depart(self, reg, when):
        for stay in self.stays:
            if stay.vessel.reg == reg and stay.departure is None:
                stay.departure = when
                self.berths[stay.berth_code].occupied_by = None
                return stay
        raise AllocationError("%s is not in port" % reg)

    # ---- dues -------------------------------------------------------------

    def days_of_stay(self, stay, month_end=None):
        end = stay.departure or month_end or datetime.datetime.now()
        delta = end - stay.arrival
        return max(1, math.ceil(delta.total_seconds() / 86400))

    def is_night_arrival(self, stay):
        h = stay.arrival.hour
        return h >= 22 or h < 5

    def dues_for_stay(self, stay, month_end=None):
        days = self.days_of_stay(stay, month_end)
        daily = stay.vessel.gross_tonnage * DUES_PER_GT_PER_DAY
        if daily < MINIMUM_DAILY_DUES:
            daily = MINIMUM_DAILY_DUES
        total = daily * days
        if self.is_night_arrival(stay):
            total = total + total * NIGHT_SURCHARGE
        if stay.vessel.home_port == "Port Merrow":
            total = total - total * HOME_PORT_DISCOUNT
        return round(total, 2)

    # ---- landings -----------------------------------------------------------

    def record_landing(self, landing):
        known = [s.vessel for s in self.stays if s.vessel.reg == landing.vessel_reg]
        if not known:
            raise AllocationError("landing from unknown vessel %s" % landing.vessel_reg)
        vessel = known[0]
        if landing.species not in vessel.species_licences:
            raise ValueError("%s is not licensed for %s" % (vessel.reg, landing.species))
        if landing.weight_kg <= 0:
            raise ValueError("weight must be positive")
        self.landings.append(landing)

    def landing_fee(self, landing):
        fee = landing.value * LANDING_FEE_RATE
        if fee < LANDING_FEE_MINIMUM:
            fee = LANDING_FEE_MINIMUM
        return round(fee, 2)

    def quota_used(self, reg, species, year):
        total = 0
        for l in self.landings:
            if l.vessel_reg == reg and l.species == species and l.when.year == year:
                total += l.weight_kg
        return total

    def quota_remaining(self, reg, species, year, quota_kg):
        return quota_kg - self.quota_used(reg, species, year)

    # ---- ice ----------------------------------------------------------------

    def sell_ice(self, reg, tonnes, when):
        self.ice_sales.append((reg, tonnes, when))

    def ice_total(self, reg, year, month):
        total = 0
        for r, t, w in self.ice_sales:
            if r == reg and w.year == year and w.month == month:
                total += t * ICE_PRICE_PER_TONNE
        return total

    # ---- invoicing ----------------------------------------------------------

    def invoice_lines(self, reg, year, month):
        lines = []
        month_start = datetime.datetime(year, month, 1)
        if month == 12:
            month_end = datetime.datetime(year + 1, 1, 1)
        else:
            month_end = datetime.datetime(year, month + 1, 1)

        for stay in self.stays:
            if stay.vessel.reg != reg:
                continue
            if stay.arrival < month_end and (stay.departure is None or stay.departure >= month_start):
                dues = self.dues_for_stay(stay, month_end)
                lines.append(("Harbour dues %s" % stay.berth_code, dues))

        for landing in self.landings:
            if landing.vessel_reg == reg and landing.when.year == year and landing.when.month == month:
                lines.append(
                    ("Landing fee %s %skg" % (landing.species, landing.weight_kg),
                     self.landing_fee(landing))
                )

        ice = self.ice_total(reg, year, month)
        if ice:
            lines.append(("Ice", round(ice, 2)))

        return lines

    def invoice_total(self, reg, year, month):
        net = sum(amount for _, amount in self.invoice_lines(reg, year, month))
        vat = round(net * VAT, 2)
        return {"net": round(net, 2), "vat": vat, "gross": round(net + vat, 2)}

    def monthly_csv(self, year, month):
        regs = sorted({s.vessel.reg for s in self.stays})
        out = io.StringIO()
        writer = csv.writer(out)
        writer.writerow(["reg", "net", "vat", "gross"])
        for reg in regs:
            t = self.invoice_total(reg, year, month)
            writer.writerow([reg, t["net"], t["vat"], t["gross"]])
        return out.getvalue()

    def landings_by_species(self, year, month):
        result = defaultdict(float)
        for l in self.landings:
            if l.when.year == year and l.when.month == month:
                result[l.species] += l.weight_kg
        return dict(result)

    def occupancy_report(self):
        rows = []
        for code, b in sorted(self.berths.items()):
            rows.append((code, b.max_length_m, b.occupied_by or "-"))
        return rows


def parse_landing_row(row):
    """Parse one row of the landing slip CSV: reg,species,kg,price,date"""
    reg, species, kg, price, date = row
    y, m, d = date.split("-")
    return Landing(reg.strip(), species.strip().lower(), float(kg), float(price),
                   datetime.date(int(y), int(m), int(d)))


def load_landings(text):
    reader = csv.reader(io.StringIO(text))
    next(reader)
    return [parse_landing_row(r) for r in reader if r]

QUOTAS_KG = {
    ("cod", 2026): 1800.0,
    ("haddock", 2026): 2500.0,
    ("plaice", 2026): 1200.0,
}


def overdue_stays(harbour, now, max_days=14):
    """Return stays that are still open and longer than max_days."""
    result = []
    for stay in harbour.stays:
        if stay.departure is None and (now - stay.arrival).days > max_days:
            result.append(stay)
    return result


def vessels_over_quota(harbour, year):
    """Return a dict reg -> list of species where landings exceed the quota."""
    over = {}
    regs = {l.vessel_reg for l in harbour.landings}
    for reg in regs:
        for (species, quota_year), quota in QUOTAS_KG.items():
            if quota_year != year:
                continue
            if harbour.quota_used(reg, species, year) > quota:
                over.setdefault(reg, []).append(species)
    return over


def berth_utilisation(harbour, start, end):
    """Share of berth-days used between two datetimes, from 0 to 1."""
    total_days = (end - start).days * len(harbour.berths)
    used = 0
    for stay in harbour.stays:
        a = max(stay.arrival, start)
        b = min(stay.departure or end, end)
        if b > a:
            used += (b - a).days
    return used / total_days


def export_landings(harbour, year, month):
    out = io.StringIO()
    writer = csv.writer(out)
    writer.writerow(["reg", "species", "kg", "price_per_kg", "value", "date"])
    for l in sorted(harbour.landings, key=lambda x: x.when):
        if l.when.year == year and l.when.month == month:
            writer.writerow([l.vessel_reg, l.species, l.weight_kg, l.price_per_kg,
                             l.value, l.when.isoformat()])
    return out.getvalue()


def average_price_per_kg(harbour, species, year, month):
    weights = 0
    values = 0
    for l in harbour.landings:
        if l.species == species and l.when.year == year and l.when.month == month:
            weights += l.weight_kg
            values += l.value
    return values / weights


def split_invoice(lines, parts):
    """Split invoice lines evenly between co-owners of a vessel."""
    share = [(label, round(amount / parts, 2)) for label, amount in lines]
    return [share for _ in range(parts)]
```

A few facts that may help. Port Merrow has 38 berths, and the invoice run is done on the first working day of each month. About 90 vessels use the harbour in a month, mostly local boats that stay for a few days. Prices are in euro. Landing slips arrive as CSV from the fish auction. The home port discount applies to vessels registered at Port Merrow, and the night surcharge was introduced two years ago for arrivals that need extra staff. Dues have been disputed twice by owners who said they were charged for days they were out at sea.

We are a network of eleven kindergartens run by a parents' cooperative, and this TypeScript module is the heart of our admin app: it handles places, waiting lists, staffing ratios and the monthly parent fees. A volunteer wrote it quickly and it has grown. Please explain what each part does, propose a refactoring (with the reasons and what the new structure would look like), and then write a good set of tests with Vitest for the parts that matter most. Call out anything you think is a bug.

```ts
// kindergarten.ts - places, waiting list, ratios and fees for the Little Oak network

export type AgeBand = "under2" | "2to3" | "3plus";

export interface Child {
  id: string;
  name: string;
  birthDate: string; // ISO yyyy-mm-dd
  centreId: string;
  siblingIds: string[];
  hoursPerWeek: number;
  allergies?: string[];
  vegetarian?: boolean;
  startDate: string;
  endDate?: string;
}

export interface Centre {
  id: string;
  name: string;
  groups: Group[];
}

export interface Group {
  id: string;
  name: string;
  band: AgeBand;
  capacity: number;
  childIds: string[];
  staffIds: string[];
}

export interface Staff {
  id: string;
  name: string;
  qualified: boolean;
  weeklyHours: number;
}

export interface WaitingEntry {
  childId: string;
  centreId: string;
  requestedStart: string;
  appliedOn: string;
  hasSiblingInCentre: boolean;
  memberFamily: boolean;
  priority?: number;
}

export interface FeeTable {
  baseHourly: number;
  mealPerDay: number;
  materialsPerMonth: number;
  incomeBands: { upTo: number; factor: number }[];
  siblingDiscount: number[]; // index 0 = second child, 1 = third child, ...
}

export const DEFAULT_FEES: FeeTable = {
  baseHourly: 1.85,
  mealPerDay: 3.9,
  materialsPerMonth: 12,
  incomeBands: [
    { upTo: 24000, factor: 0.5 },
    { upTo: 42000, factor: 0.8 },
    { upTo: 70000, factor: 1 },
    { upTo: Infinity, factor: 1.15 },
  ],
  siblingDiscount: [0.1, 0.25, 0.5],
};

const RATIO: Record<AgeBand, number> = {
  under2: 4,
  "2to3": 7,
  "3plus": 12,
};

export function ageInMonths(birthDate: string, on: string): number {
  const b = new Date(birthDate);
  const d = new Date(on);
  let months = (d.getFullYear() - b.getFullYear()) * 12 + (d.getMonth() - b.getMonth());
  if (d.getDate() < b.getDate()) months -= 1;
  return months;
}

export function bandFor(birthDate: string, on: string): AgeBand {
  const m = ageInMonths(birthDate, on);
  if (m < 24) return "under2";
  if (m < 36) return "2to3";
  return "3plus";
}

// ---------------------------------------------------------------- ratios

export interface RatioCheck {
  groupId: string;
  children: number;
  staff: number;
  qualifiedStaff: number;
  allowed: number;
  ok: boolean;
  reason?: string;
}

export function checkRatio(group: Group, staff: Staff[]): RatioCheck {
  const onGroup = staff.filter((s) => group.staffIds.includes(s.id));
  const qualified = onGroup.filter((s) => s.qualified).length;
  const allowed = onGroup.length * RATIO[group.band];
  const children = group.childIds.length;

  let ok = true;
  let reason: string | undefined;
  if (children > group.capacity) {
    ok = false;
    reason = "over capacity";
  } else if (children > allowed) {
    ok = false;
    reason = "not enough staff";
  } else if (children > 0 && qualified === 0) {
    ok = false;
    reason = "no qualified staff";
  }
  return {
    groupId: group.id,
    children,
    staff: onGroup.length,
    qualifiedStaff: qualified,
    allowed,
    ok,
    reason,
  };
}

export function checkCentre(centre: Centre, staff: Staff[]): RatioCheck[] {
  return centre.groups.map((g) => checkRatio(g, staff));
}

// ---------------------------------------------------------------- waiting list

export function scoreEntry(e: WaitingEntry, today: string): number {
  let score = 0;
  if (e.hasSiblingInCentre) score += 50;
  if (e.memberFamily) score += 20;
  const waitedDays = Math.floor(
    (new Date(today).getTime() - new Date(e.appliedOn).getTime()) / 86400000
  );
  score += Math.min(waitedDays / 30, 24);
  if (e.priority) score += e.priority;
  return score;
}

export function rankWaitingList(entries: WaitingEntry[], today: string): WaitingEntry[] {
  return entries.sort((a, b) => scoreEntry(b, today) - scoreEntry(a, today));
}

export function offerPlaces(
  centre: Centre,
  entries: WaitingEntry[],
  children: Map<string, Child>,
  today: string
): { childId: string; groupId: string }[] {
  const offers: { childId: string; groupId: string }[] = [];
  const ranked = rankWaitingList(entries.filter((e) => e.centreId === centre.id), today);
  for (const entry of ranked) {
    const child = children.get(entry.childId);
    if (!child) continue;
    const band = bandFor(child.birthDate, entry.requestedStart);
    const group = centre.groups.find(
      (g) => g.band === band && g.childIds.length + offers.filter((o) => o.groupId === g.id).length < g.capacity
    );
    if (group) offers.push({ childId: child.id, groupId: group.id });
  }
  return offers;
}

// ---------------------------------------------------------------- fees

export interface FeeInput {
  child: Child;
  householdIncome: number;
  daysAttended: number;
  month: string; // yyyy-mm
  siblingOrder: number; // 0 = eldest in the network
}

export interface FeeLine {
  label: string;
  amount: number;
}

export function incomeFactor(income: number, table: FeeTable = DEFAULT_FEES): number {
  for (const band of table.incomeBands) {
    if (income <= band.upTo) return band.factor;
  }
  return 1;
}

export function weeksInMonth(month: string): number {
  const [y, m] = month.split("-").map(Number);
  const days = new Date(y, m, 0).getDate();
  return days / 7;
}

export function monthlyFee(input: FeeInput, table: FeeTable = DEFAULT_FEES): FeeLine[] {
  const lines: FeeLine[] = [];
  const { child } = input;

  const hours = child.hoursPerWeek * weeksInMonth(input.month);
  let care = hours * table.baseHourly * incomeFactor(input.householdIncome, table);

  if (input.siblingOrder > 0) {
    const idx = Math.min(input.siblingOrder - 1, table.siblingDiscount.length - 1);
    care = care * (1 - table.siblingDiscount[idx]);
  }
  lines.push({ label: "Childcare", amount: Math.round(care * 100) / 100 });

  if (!child.vegetarian || child.vegetarian) {
    lines.push({
      label: "Meals",
      amount: Math.round(input.daysAttended * table.mealPerDay * 100) / 100,
    });
  }

  lines.push({ label: "Materials", amount: table.materialsPerMonth });
  return lines;
}

export function totalOf(lines: FeeLine[]): number {
  return lines.reduce((sum, l) => sum + l.amount, 0);
}

export function siblingOrderFor(child: Child, all: Map<string, Child>): number {
  const family = [child, ...child.siblingIds.map((id) => all.get(id)).filter(Boolean)] as Child[];
  family.sort((a, b) => a.birthDate.localeCompare(b.birthDate));
  return family.findIndex((c) => c.id === child.id);
}

// ---------------------------------------------------------------- attendance and staff hours

export interface AttendanceRecord {
  childId: string;
  date: string;
  present: boolean;
  arrivedAt?: string; // HH:MM
  leftAt?: string; // HH:MM
}

export function parseAttendanceCsv(text: string): AttendanceRecord[] {
  const rows = text.trim().split("\n").slice(1);
  return rows.map((row) => {
    const [childId, date, present, arrivedAt, leftAt] = row.split(",");
    return {
      childId,
      date,
      present: present === "1",
      arrivedAt: arrivedAt || undefined,
      leftAt: leftAt || undefined,
    };
  });
}

export function daysAttendedByChild(records: AttendanceRecord[], month: string): Record<string, number> {
  const result: Record<string, number> = {};
  for (const r of records) {
    if (!r.date.startsWith(month)) continue;
    if (r.present) result[r.childId] = (result[r.childId] || 0) + 1;
  }
  return result;
}

export function hoursBetween(from: string, to: string): number {
  const [fh, fm] = from.split(":").map(Number);
  const [th, tm] = to.split(":").map(Number);
  return (th * 60 + tm - (fh * 60 + fm)) / 60;
}

export function overtimeChildren(records: AttendanceRecord[], contractedPerDay: Record<string, number>): string[] {
  const flagged = new Set<string>();
  for (const r of records) {
    if (!r.present || !r.arrivedAt || !r.leftAt) continue;
    const actual = hoursBetween(r.arrivedAt, r.leftAt);
    if (actual > contractedPerDay[r.childId] + 0.25) flagged.add(r.childId);
  }
  return Array.from(flagged);
}

export function staffCoverage(staff: Staff[], centre: Centre): Record<string, number> {
  const coverage: Record<string, number> = {};
  for (const g of centre.groups) {
    const hours = staff
      .filter((s) => g.staffIds.includes(s.id))
      .reduce((sum, s) => sum + s.weeklyHours, 0);
    coverage[g.id] = hours / 40;
  }
  return coverage;
}

export function nextBandChange(child: Child, today: string): string | null {
  const born = new Date(child.birthDate);
  const months = ageInMonths(child.birthDate, today);
  const target = months < 24 ? 24 : months < 36 ? 36 : null;
  if (target === null) return null;
  const d = new Date(born.getFullYear(), born.getMonth() + target, born.getDate());
  return d.toISOString().slice(0, 10);
}

// ---------------------------------------------------------------- invoices

export interface Invoice {
  childId: string;
  month: string;
  lines: FeeLine[];
  total: number;
  dueDate: string;
}

export function buildInvoices(
  children: Child[],
  incomes: Record<string, number>,
  attendance: Record<string, number>,
  month: string
): Invoice[] {
  const byId = new Map(children.map((c) => [c.id, c]));
  const invoices: Invoice[] = [];
  for (const child of children) {
    if (child.endDate && child.endDate < month + "-01") continue;
    if (child.startDate > month + "-31") continue;
    const lines = monthlyFee(
      {
        child,
        householdIncome: incomes[child.id],
        daysAttended: attendance[child.id] ?? 0,
        month,
        siblingOrder: siblingOrderFor(child, byId),
      },
      DEFAULT_FEES
    );
    invoices.push({
      childId: child.id,
      month,
      lines,
      total: totalOf(lines),
      dueDate: month + "-05",
    });
  }
  return invoices;
}

export function summarise(invoices: Invoice[]): { count: number; total: number; average: number } {
  const total = invoices.reduce((s, i) => s + i.total, 0);
  return { count: invoices.length, total, average: total / invoices.length };
}

export function allergyReport(centre: Centre, children: Map<string, Child>): string[] {
  const lines: string[] = [];
  for (const g of centre.groups) {
    for (const id of g.childIds) {
      const c = children.get(id);
      if (c && c.allergies && c.allergies.length > 0) {
        lines.push(`${g.name}: ${c.name} (${c.allergies.join(", ")})`);
      }
    }
  }
  return lines;
}
```

Some background: each centre has between two and four groups, and each group has two to five staff. Fees are invoiced on the first working day of the month for the month before. Households with several children in the network get a discount on the younger children. Parents often complain that fees for children who started or left mid-month do not look right, and that the vegetarian meal price should be lower, but the price table has no field for it. The waiting list for our two biggest centres has over 200 children each.

This is the matchmaking package for our co-op shooter, written by a developer who has since left the studio, and I have inherited it with no tests. Please explain how it works piece by piece, review it carefully for bugs, race conditions and design problems (rank them by how likely they are to hurt players), and write table-driven tests for it in the standard testing package. Show the code for any fixes you recommend.

```go
// Package matchmaker groups waiting players into balanced matches.
package matchmaker

import (
	"errors"
	"fmt"
	"sort"
	"sync"
	"time"
)

// Region identifies the data centre a player prefers.
type Region string

// Mode is the kind of game a player wants to join.
type Mode string

const (
	ModeSquad   Mode = "squad"   // 4 players
	ModeRaid    Mode = "raid"    // 8 players
	ModeDuel    Mode = "duel"    // 2 players
	maxPartyLen      = 4
)

// ModeSize returns how many players a match of the given mode needs.
func ModeSize(m Mode) int {
	switch m {
	case ModeDuel:
		return 2
	case ModeSquad:
		return 4
	case ModeRaid:
		return 8
	}
	return 0
}

// Ticket is one request to be matched. A party of friends shares one ticket.
type Ticket struct {
	ID       string
	PlayerIDs []string
	Rating   int
	Region   Region
	Mode     Mode
	Enqueued time.Time
}

// Size is the number of players on the ticket.
func (t *Ticket) Size() int { return len(t.PlayerIDs) }

// Match is a group of tickets that will play together.
type Match struct {
	ID      string
	Mode    Mode
	Region  Region
	Tickets []*Ticket
	Created time.Time
}

// AverageRating returns the mean rating across all players in the match.
func (m *Match) AverageRating() float64 {
	total, count := 0, 0
	for _, t := range m.Tickets {
		total += t.Rating * t.Size()
		count += t.Size()
	}
	if count == 0 {
		return 0
	}
	return float64(total) / float64(count)
}

// Config tunes the queue.
type Config struct {
	BaseWindow   int           // rating difference allowed immediately
	WidenPerStep int           // extra allowed difference per step
	StepEvery    time.Duration // how long between each widening
	MaxWindow    int           // upper bound for the window
	MaxWait      time.Duration // tickets older than this are expired
}

// DefaultConfig returns the values used in production.
func DefaultConfig() Config {
	return Config{
		BaseWindow:   75,
		WidenPerStep: 50,
		StepEvery:    10 * time.Second,
		MaxWindow:    600,
		MaxWait:      3 * time.Minute,
	}
}

var (
	ErrDuplicate    = errors.New("matchmaker: ticket already queued")
	ErrBadMode      = errors.New("matchmaker: unknown mode")
	ErrPartyTooBig  = errors.New("matchmaker: party too large for mode")
	ErrNotFound     = errors.New("matchmaker: ticket not found")
	ErrEmptyTicket  = errors.New("matchmaker: ticket has no players")
)

// Queue holds waiting tickets and builds matches.
type Queue struct {
	mu      sync.Mutex
	cfg     Config
	tickets map[string]*Ticket
	byPlayer map[string]string
	now     func() time.Time
	nextID  int
	onMatch func(*Match)
	expired int
}

// New creates a queue. If now is nil, time.Now is used.
func New(cfg Config, now func() time.Time, onMatch func(*Match)) *Queue {
	if now == nil {
		now = time.Now
	}
	return &Queue{
		cfg:      cfg,
		tickets:  make(map[string]*Ticket),
		byPlayer: make(map[string]string),
		now:      now,
		onMatch:  onMatch,
	}
}

// Add puts a ticket into the queue.
func (q *Queue) Add(t *Ticket) error {
	size := ModeSize(t.Mode)
	if size == 0 {
		return ErrBadMode
	}
	if t.Size() == 0 {
		return ErrEmptyTicket
	}
	if t.Size() > maxPartyLen || t.Size() > size {
		return ErrPartyTooBig
	}

	q.mu.Lock()
	defer q.mu.Unlock()

	if _, ok := q.tickets[t.ID]; ok {
		return ErrDuplicate
	}
	for _, p := range t.PlayerIDs {
		if _, busy := q.byPlayer[p]; busy {
			return fmt.Errorf("%w: player %s", ErrDuplicate, p)
		}
	}
	t.Enqueued = q.now()
	q.tickets[t.ID] = t
	for _, p := range t.PlayerIDs {
		q.byPlayer[p] = t.ID
	}
	return nil
}

// Cancel removes a ticket, for example when the player leaves the lobby.
func (q *Queue) Cancel(id string) error {
	q.mu.Lock()
	defer q.mu.Unlock()
	t, ok := q.tickets[id]
	if !ok {
		return ErrNotFound
	}
	q.remove(t)
	return nil
}

// remove deletes a ticket from both indexes. The caller holds the lock.
func (q *Queue) remove(t *Ticket) {
	delete(q.tickets, t.ID)
	for _, p := range t.PlayerIDs {
		delete(q.byPlayer, p)
	}
}

// Len returns the number of waiting tickets.
func (q *Queue) Len() int {
	q.mu.Lock()
	defer q.mu.Unlock()
	return len(q.tickets)
}

// window returns the rating difference allowed for a ticket that has waited d.
func (q *Queue) window(d time.Duration) int {
	if q.cfg.StepEvery <= 0 {
		return q.cfg.MaxWindow
	}
	steps := int(d / q.cfg.StepEvery)
	w := q.cfg.BaseWindow + steps*q.cfg.WidenPerStep
	if w > q.cfg.MaxWindow {
		w = q.cfg.MaxWindow
	}
	return w
}

func abs(n int) int {
	if n < 0 {
		return -n
	}
	return n
}

// compatible reports whether two tickets may share a match.
func (q *Queue) compatible(a, b *Ticket, at time.Time) bool {
	if a.Mode != b.Mode || a.Region != b.Region {
		return false
	}
	wa := q.window(at.Sub(a.Enqueued))
	wb := q.window(at.Sub(b.Enqueued))
	allowed := wa
	if wb < wa {
		allowed = wb
	}
	return abs(a.Rating-b.Rating) <= allowed
}

// Tick expires old tickets and forms as many matches as it can.
// It returns the matches created during this call.
func (q *Queue) Tick() []*Match {
	q.mu.Lock()
	now := q.now()

	var pending []*Ticket
	for _, t := range q.tickets {
		if now.Sub(t.Enqueued) > q.cfg.MaxWait {
			q.remove(t)
			q.expired++
			continue
		}
		pending = append(pending, t)
	}

	sort.Slice(pending, func(i, j int) bool {
		return pending[i].Enqueued.Before(pending[j].Enqueued)
	})

	var matches []*Match
	used := make(map[string]bool)

	for _, seed := range pending {
		if used[seed.ID] {
			continue
		}
		size := ModeSize(seed.Mode)
		group := []*Ticket{seed}
		filled := seed.Size()

		for _, cand := range pending {
			if filled == size {
				break
			}
			if used[cand.ID] || cand.ID == seed.ID {
				continue
			}
			if filled+cand.Size() > size {
				continue
			}
			if !q.compatible(seed, cand, now) {
				continue
			}
			ok := true
			for _, g := range group {
				if !q.compatible(g, cand, now) {
					ok = false
					break
				}
			}
			if ok {
				group = append(group, cand)
				filled += cand.Size()
			}
		}

		if filled != size {
			continue
		}
		q.nextID++
		m := &Match{
			ID:      fmt.Sprintf("m-%d", q.nextID),
			Mode:    seed.Mode,
			Region:  seed.Region,
			Tickets: group,
			Created: now,
		}
		for _, g := range group {
			used[g.ID] = true
			q.remove(g)
		}
		matches = append(matches, m)
	}
	q.mu.Unlock()

	if q.onMatch != nil {
		for _, m := range matches {
			q.onMatch(m)
		}
	}
	return matches
}

// Stats is a snapshot of queue health for the dashboard.
type Stats struct {
	Waiting     int
	Expired     int
	OldestWait  time.Duration
	ByMode      map[Mode]int
}

// Snapshot returns the current statistics.
func (q *Queue) Snapshot() Stats {
	q.mu.Lock()
	defer q.mu.Unlock()
	s := Stats{
		Waiting: len(q.tickets),
		Expired: q.expired,
		ByMode:  make(map[Mode]int),
	}
	now := q.now()
	for _, t := range q.tickets {
		s.ByMode[t.Mode] += t.Size()
		if w := now.Sub(t.Enqueued); w > s.OldestWait {
			s.OldestWait = w
		}
	}
	return s
}

// Spread returns the difference between the highest and lowest ticket rating in a match.
func (m *Match) Spread() int {
	if len(m.Tickets) == 0 {
		return 0
	}
	lo, hi := m.Tickets[0].Rating, m.Tickets[0].Rating
	for _, t := range m.Tickets[1:] {
		if t.Rating < lo {
			lo = t.Rating
		}
		if t.Rating > hi {
			hi = t.Rating
		}
	}
	return hi - lo
}
